n: fixed; left: 1em; bottom: 1em; min-width: 25%; padding: .2em .4em; border: 1px solid #888; font-size: 90%; background-color: #F8F8F8; color: black; } foreignObject[data-mjx-xml] { font-family: initial; line-height: normal; overflow: visible; } mjx-container[jax="SVG"] path[data-c], mjx-container[jax="SVG"] use[data-c] { stroke-width: 3; } g[data-mml-node="xypic"] path { stroke-width: inherit; } .MathJax g[data-mml-node="xypic"] path { stroke-width: inherit; } } ∂L∂d=∑2(y^−y)⋅x3=grad_d Tensors 相比 numpy array, Tensor 最大的好处是可以利用 GPU 实现并行计算, 能够显著提高计算速度(可能达50x) 1234567891011121314151617181920212223242526272829303132333435363738394041424344# 以下是使用 tensor 实现相同的计算import torchimport mathdtype = torch.floatdevice = torch.device(&quot;cpu&quot;) # 使用 CPU 计算# device = torch.device(&quot;cuda:0&quot;) # 使用 GPU 计算# 输入x = torch.linspace(-math.pi, math.pi, 2000, device=device, dtype=dtype)y = torch.sin(x)# Randomly initialize weightsa = torch.randn((), device=device, dtype=dtype)b = torch.randn((), device=device, dtype=dtype)c = torch.randn((), device=device, dtype=dtype)d = torch.randn((), device=device, dtype=dtype)learning_rate = 1e-6for t in range(2000): # 前向传播, 计算预测值 y_pred y_pred = a + b * x + c * x ** 2 + d * x ** 3 # 计算损失 loss = (y_pred - y).pow(2).sum().item() if t % 100 == 99: print(t, loss) # 计算梯度 grad_y_pred = 2.0 * (y_pred - y) grad_a = grad_y_pred.sum() grad_b = (grad_y_pred * x).sum() grad_c = (grad_y_pred * x ** 2).sum() grad_d = (grad_y_pred * x ** 3).sum() # 更新参数 a -= learning_rate * grad_a b -= learning_rate * grad_b c -= learning_rate * grad_c d -= learning_rate * grad_dprint(f&#x27;Result: y = &#123;a.item()&#125; + &#123;b.item()&#125; x + &#123;c.item()&#125; x^2 + &#123;d.item()&#125; x^3&#x27;) Autograd 以上示例是手动实现前向和反向传播, 对于只有1~2 层的神经网络来说还可以接受. 但对于深度神经网络来说, 工作量就会变得非常恐怖了. PyTorch 通过引入计算图, 来实现自动的梯度计算. 计算图的节点是输入张量, 边是计算输出张量的函数. 例如假设 x 是一个输入张量, 那么 x.grad 里面将用于存放输出的标量相对于 x 的梯度. 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748import torchimport mathdtype = torch.floatdevice = torch.accelerator.current_accelerator().type if torch.accelerator.is_available() else &quot;cpu&quot;print(f&quot;Using &#123;device&#125; device&quot;)torch.set_default_device(device)x = torch.linspace(-1, 1, 2000, dtype=dtype)y = torch.exp(x) # 泰勒展开式为1 + x + (1/2) x**2 + (1/3!) x**3 + ...a = torch.randn((), dtype=dtype, requires_grad=True)b = torch.randn((), dtype=dtype, requires_grad=True)c = torch.randn((), dtype=dtype, requires_grad=True)d = torch.randn((), dtype=dtype, requires_grad=True)initial_loss = 1.learning_rate = 1e-5for t in range(5000): y_pred = a + b * x + c * x ** 2 + d * x ** 3 # 损失为方差和 loss = (y_pred - y).pow(2).sum() # 保存初始损失, 以便可以比对训练过程中的损失值下降情况 if t==0: initial_loss=loss.item() if t % 100 == 99: print(f&#x27;Iteration t = &#123;t:4d&#125; loss(t)/loss(0) = &#123;round(loss.item()/initial_loss, 6):10.6f&#125; a = &#123;a.item():10.6f&#125; b = &#123;b.item():10.6f&#125; c = &#123;c.item():10.6f&#125; d = &#123;d.item():10.6f&#125;&#x27;) # 自动计算梯度 loss.backward() # 手动更新参数, 注意:此处的 grad 不再是手动计算, 而 backward 时自动计算并存储在 grad 属性中 with torch.no_grad(): a -= learning_rate * a.grad b -= learning_rate * b.grad c -= learning_rate * c.grad d -= learning_rate * d.grad # 重置梯度 a.grad = None b.grad = None c.grad = None d.grad = Noneprint(f&#x27;Result: y = &#123;a.item()&#125; + &#123;b.item()&#125; x + &#123;c.item()&#125; x^2 + &#123;d.item()&#125; x^3&#x27;) 自定义 autograd autograd 运算符实际由两个函数构成,一个是前向传播函数, 它根据输入计算输出. 一个是反向传播函数, 它根据输出张量相某个标量损失的梯度计算输入张量相对同一个标量损失的梯度. 通过继承 torch.autograd.Function 可以自定义 autograd 运算符, 只需实现 forward 和 backward 函数即可. 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465import torchimport mathclass LegendrePolynomial3(torch.autograd.Function): &quot;&quot;&quot; 通过继承 torch.autograd.Function 类，并实现其中的前向传播和反向传播方法来创建自定义的自动求导函数。这些方法操作的是张量 &quot;&quot;&quot; @staticmethod def forward(ctx, input): &quot;&quot;&quot; 在前向传播中，会接收到一个包含输入数据的张量，并返回一个包含输出结果的张量。ctx是一个上下文对象，可用于暂存反向传播计算所需的信息。可以通过 ctx.save_for_backward方法缓存张量以供反向传播使用。其他对象可以直接作为 ctx对象的属性存储，例如 ctx.my_object = my_object &quot;&quot;&quot; ctx.save_for_backward(input) return 0.5 * (5 * input ** 3 - 3 * input) @staticmethod def backward(ctx, grad_output): &quot;&quot;&quot; 在反向传播中，会接收到一个包含损失相对于输出梯度的张量，然后需要计算损失相对于输入的梯度。 &quot;&quot;&quot; input, = ctx.saved_tensors return grad_output * 1.5 * (5 * input ** 2 - 1)dtype = torch.floatdevice = torch.device(&quot;cpu&quot;)# device = torch.device(&quot;cuda:0&quot;) # 使用 GPU# 创建张量来存储输入和输出# 默认情况下，requires_grad=False，这表示在反向传播过程中，我们不需要计算这些张量的梯度x = torch.linspace(-math.pi, math.pi, 2000, device=device, dtype=dtype)y = torch.sin(x)a = torch.full((), 0.0, device=device, dtype=dtype, requires_grad=True)b = torch.full((), -1.0, device=device, dtype=dtype, requires_grad=True)c = torch.full((), 0.0, device=device, dtype=dtype, requires_grad=True)d = torch.full((), 0.3, device=device, dtype=dtype, requires_grad=True)learning_rate = 5e-6for t in range(2000): P3 = LegendrePolynomial3.apply y_pred = a + b * P3(c + d * x) loss = (y_pred - y).pow(2).sum() if t % 100 == 99: print(t, loss.item()) loss.backward() with torch.no_grad(): a -= learning_rate * a.grad b -= learning_rate * b.grad c -= learning_rate * c.grad d -= learning_rate * d.grad # 重置梯度 a.grad = None b.grad = None c.grad = None d.grad = Noneprint(f&#x27;Result: y = &#123;a.item()&#125; + &#123;b.item()&#125; * P3(&#123;c.item()&#125; + &#123;d.item()&#125; x)&#x27;) nn 模块 相比 autograd 运算符, nn.Module 提供了一个更高层级的抽象, 以便能够更加便捷的构建神经网络, 它有点类似于网络中的层. nn 库中包括一些模块(Modules) 同样是基于输入张量, 计算输出张量. 但它拥有一些内部状态, 例如包含可学习参数. nn 库还包含一些常用的损失函数. 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152# -*- coding: utf-8 -*-import torchimport mathx = torch.linspace(-math.pi, math.pi, 2000)y = torch.sin(x)# y = x + x^2 + x^3p = torch.tensor([1, 2, 3])# unsqueeze 用来给张量添加新维度, -1 表示新维度添加在最末尾, 添加后, 原本的 [2000,] 变成了 [2000, 1]xu = x.unsqueeze(-1)xx = xu.pow(p) # 由于 p 的形状是 (3,), xu 的形状是 (2000, 1), pow 运算会触发广播, 使得最终的形状为 (2000, 3)# nn.Sequential 可用来顺序组合多个层# nn.Linear 线性层使用线性函数基于输入计算输出# nn.Flatten 层将线性层的输出还原为一维张量, 以便跟最终的 y 的形状相同model = torch.nn.Sequential( torch.nn.Linear(3, 1), torch.nn.Flatten(0, 1))# 使用 nn 库中 的 MSE 函数作为损失函数loss_fn = torch.nn.MSELoss(reduction=&#x27;sum&#x27;)learning_rate = 1e-6for t in range(2000): y_pred = model(xx) loss = loss_fn(y_pred, y) if t % 100 == 99: print(t, loss.item()) # 重置梯度 model.zero_grad() # 反向传播, 自动计算所有可学习参数的梯度 loss.backward() # 更新参数, 如果有使用优化器, 则此时可直接调用优化器的 step 方法自动完成参数更新 with torch.no_grad(): for param in model.parameters(): param -= learning_rate * param.gradlinear_layer = model[0]# 对于线性层, 其参数的形式为 (weight, bias)print(f&#x27;Result: y = &#123;linear_layer.bias.item()&#125; + &#123;linear_layer.weight[:, 0].item()&#125; x + &#123;linear_layer.weight[:, 1].item()&#125; x^2 + &#123;linear_layer.weight[:, 2].item()&#125; x^3&#x27;) optim nn 库使用 optim 类实现对参数优化算法的封装 123456789101112131415161718192021222324252627282930313233# -*- coding: utf-8 -*-import torchimport mathx = torch.linspace(-math.pi, math.pi, 2000)y = torch.sin(x)p = torch.tensor([1, 2, 3])xx = x.unsqueeze(-1).pow(p)model = torch.nn.Sequential( torch.nn.Linear(3, 1), torch.nn.Flatten(0, 1))loss_fn = torch.nn.MSELoss(reduction=&#x27;sum&#x27;)learning_rate = 1e-3# 使用 RMSprop 算法作为优化器optimizer = torch.optim.RMSprop(model.parameters(), lr=learning_rate)for t in range(2000): y_pred = model(xx) loss = loss_fn(y_pred, y) if t % 100 == 99: print(t, loss.item()) optimizer.zero_grad() loss.backward() # 更新参数 optimizer.step()linear_layer = model[0]print(f&#x27;Result: y = &#123;linear_layer.bias.item()&#125; + &#123;linear_layer.weight[:, 0].item()&#125; x + &#123;linear_layer.weight[:, 1].item()&#125; x^2 + &#123;linear_layer.weight[:, 2].item()&#125; x^3&#x27;) 自定义 Module 继承 nn.Module, 实现 forward 方法返回输出张量即可 12345678910111213141516171819202122232425262728293031323334353637383940# -*- coding: utf-8 -*-import torchimport mathclass Polynomial3(torch.nn.Module): def __init__(self): super().__init__() self.a = torch.nn.Parameter(torch.randn(())) self.b = torch.nn.Parameter(torch.randn(())) self.c = torch.nn.Parameter(torch.randn(())) self.d = torch.nn.Parameter(torch.randn(())) def forward(self, x): return self.a + self.b * x + self.c * x ** 2 + self.d * x ** 3 def string(self): # 可以添加一些自定义方法 return f&#x27;y = &#123;self.a.item()&#125; + &#123;self.b.item()&#125; x + &#123;self.c.item()&#125; x^2 + &#123;self.d.item()&#125; x^3&#x27;x = torch.linspace(-math.pi, math.pi, 2000)y = torch.sin(x)model = Polynomial3()# 创建损失函数和优化器criterion = torch.nn.MSELoss(reduction=&#x27;sum&#x27;)optimizer = torch.optim.SGD(model.parameters(), lr=1e-6)for t in range(2000): y_pred = model(x) loss = criterion(y_pred, y) if t % 100 == 99: print(t, loss.item()) optimizer.zero_grad() loss.backward() optimizer.step()print(f&#x27;Result: &#123;model.string()&#125;&#x27;) 控制流+权重共享 在前向传播中引入条件分支, 这会导致不同的计算图路径. 由于 Pytorch 会动态构建计算图, 因此能够很好的支持这种条件分支. 123456789101112131415161718192021222324252627282930313233343536373839404142# -*- coding: utf-8 -*-import randomimport torchimport mathclass DynamicNet(torch.nn.Module): def __init__(self): super().__init__() self.a = torch.nn.Parameter(torch.randn(())) self.b = torch.nn.Parameter(torch.randn(())) self.c = torch.nn.Parameter(torch.randn(())) self.d = torch.nn.Parameter(torch.randn(())) self.e = torch.nn.Parameter(torch.randn(())) def forward(self, x): y = self.a + self.b * x + self.c * x ** 2 + self.d * x ** 3 for exp in range(4, random.randint(4, 6)): y = y + self.e * x ** exp # exp 的取值范围为 4 或 5, 随机的 return y def string(self): return f&#x27;y = &#123;self.a.item()&#125; + &#123;self.b.item()&#125; x + &#123;self.c.item()&#125; x^2 + &#123;self.d.item()&#125; x^3 + &#123;self.e.item()&#125; x^4 ? + &#123;self.e.item()&#125; x^5 ?&#x27;x = torch.linspace(-math.pi, math.pi, 2000)y = torch.sin(x)model = DynamicNet()criterion = torch.nn.MSELoss(reduction=&#x27;sum&#x27;)optimizer = torch.optim.SGD(model.parameters(), lr=1e-8, momentum=0.9)for t in range(30000): y_pred = model(x) loss = criterion(y_pred, y) if t % 2000 == 1999: print(t, loss.item()) optimizer.zero_grad() loss.backward() optimizer.step()print(f&#x27;Result: &#123;model.string()&#125;&#x27;) 梯度 requires_grad 假设存在以下示例网络: #mjx-8a5bfa4{ display:contents; mjx-assistive-mml { user-select: text !important; clip: auto !important; color: rgba(0,0,0,0); } mjx-container[jax="SVG"] { direction: ltr; } mjx-container[jax="SVG"] > svg { overflow: visible; min-height: 1px; min-width: 1px; } mjx-container[jax="SVG"] > svg a { fill: blue; stroke: blue; } mjx-assistive-mml { position: absolute !important; top: 0px; left: 0px; clip: rect(1px, 1px, 1px, 1px); padding: 1px 0px 0px 0px !important; border: 0px !important; display: block !important; width: auto !important; overflow: hidden !important; -webkit-touch-callout: none; -webkit-user-select: none; -khtml-user-select: none; -moz-user-select: none; -ms-user-select: none; user-select: none; } mjx-assistive-mml[display="block"] { width: 100% !important; } mjx-container[jax="SVG"][display="true"] { display: block; text-align: center; margin: 1em 0; } mjx-container[jax="SVG"][display="true"][width="full"] { display: flex; } mjx-container[jax="SVG"][justify="left"] { text-align: left; } mjx-container[jax="SVG"][justify="right"] { text-align: right; } g[data-mml-node="merror"] > g { fill: red; stroke: red; } g[data-mml-node="merror"] > rect[data-background] { fill: yellow; stroke: none; } g[data-mml-node="mtable"] > line[data-line], svg[data-table] > g > line[data-line] { stroke-width: 70px; fill: none; } g[data-mml-node="mtable"] > rect[data-frame], svg[data-table] > g > rect[data-frame] { stroke-width: 70px; fill: none; } g[data-mml-node="mtable"] > .mjx-dashed, svg[data-table] > g > .mjx-dashed { stroke-dasharray: 140; } g[data-mml-node="mtable"] > .mjx-dotted, svg[data-table] > g > .mjx-dotted { stroke-linecap: round; stroke-dasharray: 0,140; }