-table] > g > line[data-line] { stroke-width: 70px; fill: none; } g[data-mml-node="mtable"] > rect[data-frame], svg[data-table] > g > rect[data-frame] { stroke-width: 70px; fill: none; } g[data-mml-node="mtable"] > .mjx-dashed, svg[data-table] > g > .mjx-dashed { stroke-dasharray: 140; } g[data-mml-node="mtable"] > .mjx-dotted, svg[data-table] > g > .mjx-dotted { stroke-linecap: round; stroke-dasharray: 0,140; } g[data-mml-node="mtable"] > g > svg { overflow: visible; } [jax="SVG"] mjx-tool { display: inline-block; position: relative; width: 0; height: 0; } [jax="SVG"] mjx-tool > mjx-tip { position: absolute; top: 0; left: 0; } mjx-tool > mjx-tip { display: inline-block; padding: .2em; border: 1px solid #888; font-size: 70%; background-color: #F8F8F8; color: black; box-shadow: 2px 2px 5px #AAAAAA; } g[data-mml-node="maction"][data-toggle] { cursor: pointer; } mjx-status { display: block; position: fixed; left: 1em; bottom: 1em; min-width: 25%; padding: .2em .4em; border: 1px solid #888; font-size: 90%; background-color: #F8F8F8; color: black; } foreignObject[data-mjx-xml] { font-family: initial; line-height: normal; overflow: visible; } mjx-container[jax="SVG"] path[data-c], mjx-container[jax="SVG"] use[data-c] { stroke-width: 3; } g[data-mml-node="xypic"] path { stroke-width: inherit; } .MathJax g[data-mml-node="xypic"] path { stroke-width: inherit; } } ∂y∂x=∂fk∂fk−1⋅∂fk−1∂fk−2⋅⋯⋅∂f1∂x 前向传播之后生成的计算图: 如果一个节点不是由带 requires_grad=True 的张量计算出来的, 那么它就是一个叶子节点, 否则就是非叶子节点. 对于非叶子节点, 其 requires_grad=True 必然是 True, 不然反向传播就无法成功了. 对于叶子节点, 则在初始化时, 需要显式的设置参数 requires_grad=True (默认是 False, 如果初始化时没有设置, 可通过调用 requires_grad_() 方法后补) retain_grad 在反向传播时,非叶子节点的梯度是会计算的, 但是不会保存在非叶子节点(张量)的 .grad 属性上, 因此它无法使用 .grad 直接访问. 除非显式的设置参数 retain_grad=True 1234567891011121314151617181920z = (x @ W) + by_pred = F.relu(z)loss = F.mse_loss(y_pred, y)# 显式要求保存这几个张量的梯度z.retain_grad()y_pred.retain_grad()loss.retain_grad()# 重置(避免累积)W.grad = Noneb.grad = Noneloss.backward()print(f&quot;&#123;W.grad=&#125;&quot;)print(f&quot;&#123;b.grad=&#125;&quot;)print(f&quot;&#123;z.grad=&#125;&quot;)print(f&quot;&#123;y_pred.grad=&#125;&quot;)print(f&quot;&#123;loss.grad=&#125;&quot;) 1234567W.grad=tensor([[3., 3.], [3., 3.], [3., 3.]])b.grad=tensor([[3., 3.]])z.grad=tensor([[3., 3.]])y_pred.grad=tensor([[3., 3.]])loss.grad=tensor(1.) 对于叶子节点, 如果 requires_grad=True, 那么默认是保存梯度的. 此时再额外调用 retain_grad() 属于冗余的操作. 但如果叶子节点的 requires_grad=False 的话, 那么调用 retain_grad() 方法会报错, 因为该节点的梯度不会被计算, 因此自然也无法保存. 所以说, retain_grad() 只在非叶子节点的场景中使用. 主存到显存 主存是分块的, 当 OS 尝试从某个主存块中读取数据却找不到时, 会触发触常, 然后 OS 会从磁盘加载数据到内存中. 同理, 此时如果主存已满, 则 OS 会将部分数据移动到磁盘上, 以便主存能够腾出空间容纳新的数据. 分块的目的是为了能够更充分的利用内存空间, 但是代价是数据的物理内存地址可能不连续. 此时将无法充分发挥 DMA 的效率, 导致将数据复制到 GPU 前需要多一次整理的动作(将数据先复制到缓冲区, 再从缓冲区复制到 GPU), 带来了额外的开锁. 数据在内存中也可以显式设置为固定类型(页锁定, pin_memory), 对于页锁定内在, 它不会被交换到磁盘. 当 OS 加载一个文件时, 它并不会一下子将所有数据都加载到内存中, 而是等到使用时, 如果内存中找不到, 才会触发数据的加载. 当尝试将数据从主存复制到 GPU 的显存时, 由于数据有可能不在主存中, 而是在磁盘中. 为避免等待 IO, 这个复制过程通常是异步的, non_blocking=True 从页锁定的主存中复制数据会更快, 因为数据已经提前加载到内存中了. 同时由于物理地址连续, 可以直接使用 DMA 读取. 数据从主存复制到显存时, CUDA 会自动处理好数据同步问题, 不会出现要读取数据时, 数据却不存在导致报错的情况. 反之, 如果是将数据从显存拷贝到主存, 则需要手工同步一下, 才能保证读取数据前, 数据已经拷贝完成. 梯度可视化 方便排查处理训练过程中出现的梯度消失或梯度爆炸问题. 示例: 设计两个简单的模型, 一个使用 BatchNorm, 一个没有使用. 并跟踪梯度变化, 以便观察 BatchNorm 能否缓解梯度消失问题. 123456789101112131415161718192021222324252627def fc_layer(in_size, out_size, norm_layer): &quot;&quot;&quot;Return a stack of linear-&gt;norm-&gt;sigmoid layers&quot;&quot;&quot; return nn.Sequential(nn.Linear(in_size, out_size), norm_layer(out_size), nn.Sigmoid())class Net(nn.Module): &quot;&quot;&quot;Define a network that has num_layers of linear-&gt;norm-&gt;sigmoid transformations&quot;&quot;&quot; def __init__(self, in_size=28*28, hidden_size=128, out_size=10, num_layers=3, batchnorm=False): super().__init__() if batchnorm is False: norm_layer = nn.Identity else: norm_layer = nn.BatchNorm1d layers = [] layers.append(fc_layer(in_size, hidden_size, norm_layer)) for i in range(num_layers-1): layers.append(fc_layer(hidden_size, hidden_size, norm_layer)) layers.append(nn.Linear(hidden_size, out_size)) self.layers = nn.Sequential(*layers) def forward(self, x): x = torch.flatten(x, 1) return self.layers(x) 初始化数据 12345678910111213# set up dummy datax = torch.randn(10, 28, 28)y = torch.randint(10, (10, ))# init modelmodel_bn = Net(batchnorm=True, num_layers=3)model_nobn = Net(batchnorm=False, num_layers=3)model_bn.train()model_nobn.train()optimizer_bn = optim.SGD(model_bn.parameters(), lr=0.01, momentum=0.9)optimizer_nobn = optim.SGD(model_nobn.parameters(), lr=0.01, momentum=0.9) 12print(model_bn.layers[0])print(model_nobn.layers[0]) 12345678910Sequential( (0): Linear(in_features=784, out_features=128, bias=True) (1): BatchNorm1d(128, eps=1e-05, momentum=0.1, affine=True, track_running_stats=True) (2): Sigmoid())Sequential( (0): Linear(in_features=784, out_features=128, bias=True) (1): Identity() (2): Sigmoid()) 注册钩子 为了能够读取中间状态的数据, 相比使用 retain_grad(), 更推荐的方法是注册反向传播钩子(backward pass hook). 定义钩子: 123456789101112131415161718192021222324def hook_forward(module_name, grads, hook_backward): def hook(module, args, output): # 在前向传播过程中, 为每个输出张量注册反向钩子 output.register_hook(hook_backward(module_name, grads)) return hookdef hook_backward(module_name, grads): def hook(grad): # 反向传播钩子, 用来收集梯度 grads.append((module_name, grad)) return hookdef get_all_layers(model, hook_forward, hook_backward): layers = dict() grads = [] for name, layer in model.named_modules(): # 仅处理叶子模块(没有子模块) if any(layer.children()) is False: layers[layer] = name layer.register_forward_hook(hook_forward(name, grads, hook_backward)) return layers, gradslayers_bn, grads_bn = get_all_layers(model_bn, hook_forward, hook_backward)layers_nobn, grads_nobn = get_all_layers(model_nobn, hook_forward, hook_backward) 训练并可视化 12345678910111213141516171819202122epochs = 10for epoch in range(epochs): # 每轮训练前先清空, 避免累积 grads_bn.clear() grads_nobn.clear() optimizer_bn.zero_grad() optimizer_nobn.zero_grad() y_pred_bn = model_bn(x) y_pred_nobn = model_nobn(x) loss_bn = F.cross_entropy(y_pred_bn, y) loss_nobn = F.cross_entropy(y_pred_nobn, y) loss_bn.backward() loss_nobn.backward() optimizer_bn.step() optimizer_nobn.step() 12345678910111213def get_grads(grads): layer_idx = [] avg_grads = [] for idx, (name, grad) in enumerate(grads): if grad is not None: avg_grad = grad.abs().mean() avg_grads.append(avg_grad) # idx is backwards since we appended in backward pass layer_idx.append(len(grads) - 1 - idx) return layer_idx, avg_gradslayer_idx_bn, avg_grads_bn = get_grads(grads_bn)layer_idx_nobn, avg_grads_nobn = get_grads(grads_nobn) 123456789fig, ax = plt.subplots()ax.plot(layer_idx_bn, avg_grads_bn, label=&quot;With BatchNorm&quot;, marker=&quot;o&quot;)ax.plot(layer_idx_nobn, avg_grads_nobn, label=&quot;Without BatchNorm&quot;, marker=&quot;x&quot;)ax.set_xlabel(&quot;Layer depth&quot;)ax.set_ylabel(&quot;Average gradient&quot;)ax.set_title(&quot;Gradient flow&quot;)ax.grid(True)ax.legend()plt.show() 分布式训练 DDP 数据并行, 每张显卡部署相同的模型和优化器. 每张显卡训练的数据不同, 因此在更新参数前, 需要先同步数据, 之后再统一更新参数, 确保更新后的模型参数是每张显卡上面是一样的. DistributedSampler 可用来确保每张显卡获得的数据不重复 数据的同步是可以并行的, 例如有 4 张显卡, 每次同步 1/4 到另外一张显卡上. 通过使用环状同步, 可以实现同步的并行. 相较早期更简单的 DataParallel, DDP 的性能更好一些, 二者的对比如下: 特性 DataParallel DistributedDataParallel 开销 更大；模型在每次前向传播时都会被复制并销毁 模型仅复制一次 并行支持 仅支持单机并行 支持扩展到多台机器 性能 速度较慢；在单个进程中使用多线程，会遇到全局解释器锁（GIL）竞争 速度更快（无 GIL 竞争），因为它使用多进程 以下是单 GPU 训练时的代码脚本 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182import torchimport torch.nn.functional as Ffrom torch.utils.data import Dataset, DataLoaderfrom datautils import MyTrainDatasetclass Trainer: def __init__( self, model: torch.nn.Module, train_data: DataLoader, optimizer: torch.optim.Optimizer, gpu_id: int, save_every: int, ) -&gt; None: self.gpu_id = gpu_id self.model = model.to(gpu_id) self.train_data = train_data self.optimizer = optimizer self.save_every = save_every def _run_batch(self, source, targets): self.optimizer.zero_grad() output = self.model(source) loss = F.cross_entropy(output, targets) loss.backward() self.optimizer.step() def _run_epoch(self, epoch): b_sz = len(next(iter(self.train_data))[0]) print(f&quot;[GPU&#123;self.gpu_id&#125;] Epoch &#123;epoch&#125; | Batchsize: &#123;b_sz&#125; | Steps: &#123;len(self.train_data)&#125;&quot;) for source, targets in self.train_data: source = source.to(self.gpu_id) targets = targets.to(self.gpu_id) self._run_batch(source, targets) def _save_checkpoint(self, epoch): ckp = self.model.state_dict() PATH = &quot;checkpoint.pt&quot; torch.save(ckp, PATH) print(f&quot;Epoch &#123;epoch&#125; | Training checkpoint saved at &#123;PATH&#125;&quot;) def train(self, max_epochs: int): for epoch in range(max_epochs): self._run_epoch(epoch) if epoch % self.save_every == 0: self._save_checkpoint(epoch)def load_train_objs(): train_set = MyTrainDataset(2048) # 虚拟一份数据集 model = torch.nn.Linear(20, 1) # 用一个线性层模拟待训练模型 optimizer = torch.optim.SGD(model.parameters(), lr=1e-3) return train_set, model, optimizerdef prepare_dataloader(dataset: Dataset, batch_size: int): return DataLoader( dataset, batch_size=batch_size, pin_memory=True, shuffle=True )def main(device, total_epochs, save_every, batch_size): dataset, model, optimizer = load_train_objs() train_data = prepare_dataloader(dataset, batch_size) trainer = Trainer(model, train_data, optimizer, device, save_every) trainer.train(total_epochs)if __name__ == &quot;__main__&quot;: import argparse parser = argparse.ArgumentParser(description=&#x27;simple distributed training job&#x27;) parser.add_argument(&#x27;total_epochs&#x27;, type=int, help=&#x27;Total epochs to train the model&#x27;) parser.add_argument(&#x27;save_every&#x27;, type=int, help=&#x27;How often to save a snapshot&#x27;) parser.add_argument(&#x27;--batch_size&#x27;, default=32, type=int, help=&#x27;Input batch size on each device (default: 32)&#x27;) args = parser.parse_args() device = 0 # shorthand for cuda:0 main(device, args.total_epochs, args.save_every, args.batch_size) 以下是切换到 DDP 模式进行训练的脚本: 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108import torchimport torch.nn.functional as Ffrom torch.utils.data import Dataset, DataLoaderfrom datautils import MyTrainDataset# 引入一些新的库import torch.multiprocessing as mp # 管理多个进程的不同 GPUfrom torch.utils.data.distributed import DistributedSampler # 按 GPU 切分数据from torch.nn.parallel import DistributedDataParallel as DDP # 数据并行模式from torch.distributed import init_process_group, destroy_process_group # 进程组管理import os# 设置 DDP 的参数def ddp_setup(rank, world_size): &quot;&quot;&quot; Args: rank: 每个进程的识别代号 world_size: 进程总数 &quot;&quot;&quot; os.environ[&quot;MASTER_ADDR&quot;] = &quot;localhost&quot; # 因为是一机多卡, 所以 IP 地址是自己 os.environ[&quot;MASTER_PORT&quot;] = &quot;12355&quot; # 监听的端口 torch.cuda.set_device(rank) # 使用 nccl 库负责 CUDA GPU 间的通讯(XPU 用 xccl, CPU 用 gloo) # init_process_group 负责初始化分布式训练的进程组 init_process_group(backend=&quot;nccl&quot;, rank=rank, world_size=world_size)class Trainer: def __init__( self, model: torch.nn.Module, train_data: DataLoader, optimizer: torch.optim.Optimizer, gpu_id: int, save_every: int, ) -&gt; None: self.gpu_id = gpu_id self.model = model.to(gpu_id) self.train_data = train_data self.optimizer = optimizer self.save_every = save_every self.model = DDP(model, device_ids=[gpu_id]) # 用 DDP 对 model 进行封装 def _run_batch(self, source, targets): self.optimizer.zero_grad() output = self.model(source) loss = F.cross_entropy(output, targets) loss.backward() self.optimizer.step() def _run_epoch(self, epoch): b_sz = len(next(iter(self.train_data))[0]) print(f&quot;[GPU&#123;self.gpu_id&#125;] Epoch &#123;epoch&#125; | Batchsize: &#123;b_sz&#125; | Steps: &#123;len(self.train_data)&#125;&quot;) self.train_data.sampler.set_epoch(epoch) # 调用 set_epoch 模拟 shuffle for source, targets in self.train_data: source = source.to(self.gpu_id) targets = targets.to(self.gpu_id) self._run_batch(source, targets) def _save_checkpoint(self, epoch): ckp = self.model.module.state_dict() PATH = &quot;checkpoint.pt&quot; torch.save(ckp, PATH) print(f&quot;Epoch &#123;epoch&#125; | Training checkpoint saved at &#123;PATH&#125;&quot;) def train(self, max_epochs: int): for epoch in range(max_epochs): self._run_epoch(epoch) # 仅让一个 GPU 负责保存模型参数即可, 毕竟所有 GPU 上的模型是相同的, 没必要重复保存 if self.gpu_id == 0 and epoch % self.save_every == 0: self._save_checkpoint(epoch)def load_train_objs(): train_set = MyTrainDataset(2048) model = torch.nn.Linear(20, 1) optimizer = torch.optim.SGD(model.parameters(), lr=1e-3) return train_set, model, optimizerdef prepare_dataloader(dataset: Dataset, batch_size: int): return DataLoader( dataset, batch_size=batch_size, pin_memory=True, shuffle=False, # 关闭 shuffle sampler=DistributedSampler(dataset) # 使用 DistributedSampler 切分训练数据 )# 增加了 rank 和 world_size 参数def main(rank: int, world_size: int, save_every: int, total_epochs: int, batch_size: int): ddp_setup(rank, world_size) # 初始化 DDP dataset, model, optimizer = load_train_objs() train_data = prepare_dataloader(dataset, batch_size) trainer = Trainer(model, train_data, optimizer, rank, save_every) # 用 rank 替换 device trainer.train(total_epochs) destroy_process_group() # 训练结束后销毁进程if __name__ == &quot;__main__&quot;: import argparse parser = argparse.ArgumentParser(description=&#x27;simple distributed training job&#x27;) parser.add_argument(&#x27;total_epochs&#x27;, type=int, help=&#x27;Total epochs to train the model&#x27;) parser.add_argument(&#x27;save_every&#x27;, type=int, help=&#x27;How often to save a snapshot&#x27;) parser.add_argument(&#x27;--batch_size&#x27;, default=32, type=int, help=&#x27;Input batch size on each device (default: 32)&#x27;) args = parser.parse_args() world_size = torch.cuda.device_count() # 获取可用的 GPU 数量 mp.spawn(main, args=(world_size, args.save_every, args.total_epochs, args.batch_size), nprocs=world_size) # 孵化多个进程 异常处理 由于涉及多节点多进程多个 GPU, 训练过程中出现异常的概率会大幅上升. 为避免出现中断导致从头开始训练, 需要引入一个从中断处继续训练的机制. 可使用 pytorch torchrun 提供的 snapshot 功能, 为每轮训练保存快照, 这样当出现中断时, 就可以从快照中快速恢复. 虽然每轮或每几轮会保存 checkpoint 检查点, 但是检查点只包括模型的参数, 没有保存中断前的整个状态, 例如epoch 轮次等. 因此需要在 snapshot 中保存更丰富的信息以便恢复中断时的状态 使用 torchrun 后的几个变化: 无须手动设置 rank, world_size 等环境变量, torchrun 会自动计算 无须手动使用 mp.spawn 孵化多个进程, torchrun 会自动创建多个进程(单节点也可以适用)； 当某个进程出现异常导致训练中断后, torchrun 会中断其他所有进程. 再次运行 torchrun 会从中断处继续训练, 损失多少取决于快照保存的时间间隔. 在训练过程中, 如果添加或删除节点, torchrun 会自动在所有节点上重启所有进程, 无需手动干预 引入 snapshot 后, 代码结构大致变成下面这个样子: 1234567891011def main(): load_snapshot(snapshot_path) # 运行时优先加载快照(如有) initialize() train()def train(): for batch in iter(dataset): train_step(batch) if should_checkpoint: # 在训练过程中设置保存快照的条件 save_snapshot(snapshot_path) 以下是引入 torchrun 和 snapshot 后的代码: 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108109110111112113114115116117import torchimport torch.nn.functional as Ffrom torch.utils.data import Dataset, DataLoaderfrom datautils import MyTrainDatasetimport torch.multiprocessing as mpfrom torch.utils.data.distributed import DistributedSamplerfrom torch.nn.parallel import DistributedDataParallel as DDPfrom torch.distributed import init_process_group, destroy_process_groupimport os# torchrun 会自动设置 RANK, 因此无需再手动配置 rank 和 world_sizedef ddp_setup(): torch.cuda.set_device(int(os.environ[&quot;LOCAL_RANK&quot;])) # 使用 torchrun 设置的 RANK 环境变量 init_process_group(backend=&quot;nccl&quot;)class Trainer: def __init__( self, model: torch.nn.Module, train_data: DataLoader, optimizer: torch.optim.Optimizer, save_every: int, snapshot_path: str, # 快照保存路径 ) -&gt; None: self.gpu_id = int(os.environ[&quot;LOCAL_RANK&quot;]) # 使用 torchrun 设置的 RANK 环境变量 self.model = model.to(self.gpu_id) self.train_data = train_data self.optimizer = optimizer self.save_every = save_every self.epochs_run = 0 self.snapshot_path = snapshot_path if os.path.exists(snapshot_path): # 如有快照, 优先加载, 而非从头开始 print(&quot;Loading snapshot&quot;) self._load_snapshot(snapshot_path) self.model = DDP(self.model, device_ids=[self.gpu_id]) # 加载快照 def _load_snapshot(self, snapshot_path): loc = f&quot;cuda:&#123;self.gpu_id&#125;&quot; snapshot = torch.load(snapshot_path, map_location=loc) # 读取快照中的数据 self.model.load_state_dict(snapshot[&quot;MODEL_STATE&quot;]) self.epochs_run = snapshot[&quot;EPOCHS_RUN&quot;] print(f&quot;Resuming training from snapshot at Epoch &#123;self.epochs_run&#125;&quot;) def _run_batch(self, source, targets): self.optimizer.zero_grad() output = self.model(source) loss = F.cross_entropy(output, targets) loss.backward() self.optimizer.step() def _run_epoch(self, epoch): b_sz = len(next(iter(self.train_data))[0]) print(f&quot;[GPU&#123;self.gpu_id&#125;] Epoch &#123;epoch&#125; | Batchsize: &#123;b_sz&#125; | Steps: &#123;len(self.train_data)&#125;&quot;) self.train_data.sampler.set_epoch(epoch) for source, targets in self.train_data: source = source.to(self.gpu_id) targets = targets.to(self.gpu_id) self._run_batch(source, targets) # 保存快照, 取代 checkpoint 保存 def _save_snapshot(self, epoch): # 保存 model.module.state_dict 和 epoch 两个值, 原 checkpoint 只保存了前者 snapshot = &#123; &quot;MODEL_STATE&quot;: self.model.module.state_dict(), &quot;EPOCHS_RUN&quot;: epoch, &#125; torch.save(snapshot, self.snapshot_path) print(f&quot;Epoch &#123;epoch&#125; | Training snapshot saved at &#123;self.snapshot_path&#125;&quot;) def train(self, max_epochs: int): # 从 epochs_run 处开始, 不再从 0 开始 for epoch in range(self.epochs_run, max_epochs): self._run_epoch(epoch) # 按 save_every 保存快照(仅在 GPU:0 上面保存, 之前是保存 checkpoint) if self.gpu_id == 0 and epoch % self.save_every == 0: self._save_snapshot(epoch)def load_train_objs(): train_set = MyTrainDataset(2048) # load your dataset model = torch.nn.Linear(20, 1) # load your model optimizer = torch.optim.SGD(model.parameters(), lr=1e-3) return train_set, model, optimizerdef prepare_dataloader(dataset: Dataset, batch_size: int): return DataLoader( dataset, batch_size=batch_size, pin_memory=True, shuffle=False, sampler=DistributedSampler(dataset) )def main(save_every: int, total_epochs: int, batch_size: int, snapshot_path: str = &quot;snapshot.pt&quot;): ddp_setup() dataset, model, optimizer = load_train_objs() train_data = prepare_dataloader(dataset, batch_size) trainer = Trainer(model, train_data, optimizer, save_every, snapshot_path) trainer.train(total_epochs) destroy_process_group()if __name__ == &quot;__main__&quot;: import argparse parser = argparse.ArgumentParser(description=&#x27;simple distributed training job&#x27;) parser.add_argument(&#x27;total_epochs&#x27;, type=int, help=&#x27;Total epochs to train the model&#x27;) parser.add_argument(&#x27;save_every&#x27;, type=int, help=&#x27;How often to save a snapshot&#x27;) parser.add_argument(&#x27;--batch_size&#x27;, default=32, type=int, help=&#x27;Input batch size on each device (default: 32)&#x27;) args = parser.parse_args() # 直接调用 main 函数, 由 torchrun 进行调度, 不再需要手动 mp.spawn main(args.save_every, args.total_epochs, args.batch_size) 1torchrun --standalone --nproc_per_node=4 multigpu_torchrun.py 50 10 多节点训练 当使用多个节点时, 因为快照只保存在其中一台机器(节点)上, 因此当出现异常导致所有进程重启时, 所有节点都需要从该节点获取快照, 因此有两点很重要, 一是该节点的带宽尽量大一些； 二是确保 TCP 能够连通(注意检查防火墙设置) 由于多节点需要通过网络进行通讯, 其带宽远小于相同节点多个 GPU 之间的通讯带宽, 因此 1 机多卡的训练速度要远大于多机单卡； 有两种方法进行多节点的训练: 在每个节点上面运行相同参数的 torchrun 命令； 创建一个集群, 然后使用一个管理器统一进行调度(例如 slurm)； 在单节点场景中, gpu_id 来自 torchrun 设置的 LOCAL_RANK 环境变量. 在多点节场景中, 还需要使用 torchrun 设置的另外一个全局 RANK 环境变量, 以便唯一识别每个 GPU 进程. 当出现异常导致 torchrun 重启所有进程时, 每个进程获得的 LOCAL_RANK 和 RANK 变量可能和之前的不同. torchrun 支持异构扩展, 即每个节点的 GPU 数量可以不同, 例如有些节点配备 4 个 GPU, 有些配备 2 个GPU 调试时, 可设置环境变量 NCCL_DEBUG=INFO, 这样可以查看详细的日志. 以下是使用多节点训练时的代码变更: 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108109110111112import torchimport torch.nn.functional as Ffrom torch.utils.data import Dataset, DataLoaderfrom datautils import MyTrainDatasetimport torch.multiprocessing as mpfrom torch.utils.data.distributed import DistributedSamplerfrom torch.nn.parallel import DistributedDataParallel as DDPfrom torch.distributed import init_process_group, destroy_process_groupimport osdef ddp_setup(): torch.cuda.set_device(int(os.environ[&quot;LOCAL_RANK&quot;])) init_process_group(backend=&quot;nccl&quot;)class Trainer: def __init__( self, model: torch.nn.Module, train_data: DataLoader, optimizer: torch.optim.Optimizer, save_every: int, snapshot_path: str, ) -&gt; None: self.local_rank = int(os.environ[&quot;LOCAL_RANK&quot;]) # 原 gpu_id 属性替换为 local_rank self.global_rank = int(os.environ[&quot;RANK&quot;]) # 此处使用 RANK 来唯一识别 GPU 进程 self.model = model.to(self.local_rank) self.train_data = train_data self.optimizer = optimizer self.save_every = save_every self.epochs_run = 0 self.snapshot_path = snapshot_path if os.path.exists(snapshot_path): print(&quot;Loading snapshot&quot;) self._load_snapshot(snapshot_path) self.model = DDP(self.model, device_ids=[self.local_rank]) def _load_snapshot(self, snapshot_path): loc = f&quot;cuda:&#123;self.local_rank&#125;&quot; snapshot = torch.load(snapshot_path, map_location=loc) self.model.load_state_dict(snapshot[&quot;MODEL_STATE&quot;]) self.epochs_run = snapshot[&quot;EPOCHS_RUN&quot;] print(f&quot;Resuming training from snapshot at Epoch &#123;self.epochs_run&#125;&quot;) def _run_batch(self, source, targets): self.optimizer.zero_grad() output = self.model(source) loss = F.cross_entropy(output, targets) loss.backward() self.optimizer.step() def _run_epoch(self, epoch): b_sz = len(next(iter(self.train_data))[0]) print(f&quot;[GPU&#123;self.global_rank&#125;] Epoch &#123;epoch&#125; | Batchsize: &#123;b_sz&#125; | Steps: &#123;len(self.train_data)&#125;&quot;) # 打印日志时, 使用 global_rank 进行区分不同的 GPU 进程 self.train_data.sampler.set_epoch(epoch) for source, targets in self.train_data: source = source.to(self.local_rank) targets = targets.to(self.local_rank) self._run_batch(source, targets) def _save_snapshot(self, epoch): snapshot = &#123; &quot;MODEL_STATE&quot;: self.model.module.state_dict(), &quot;EPOCHS_RUN&quot;: epoch, &#125; torch.save(snapshot, self.snapshot_path) print(f&quot;Epoch &#123;epoch&#125; | Training snapshot saved at &#123;self.snapshot_path&#125;&quot;) def train(self, max_epochs: int): for epoch in range(self.epochs_run, max_epochs): self._run_epoch(epoch) if self.global_rank == 0 and epoch % self.save_every == 0: self._save_snapshot(epoch)def load_train_objs(): train_set = MyTrainDataset(2048) # load your dataset model = torch.nn.Linear(20, 1) # load your model optimizer = torch.optim.SGD(model.parameters(), lr=1e-3) return train_set, model, optimizerdef prepare_dataloader(dataset: Dataset, batch_size: int): return DataLoader( dataset, batch_size=batch_size, pin_memory=True, shuffle=False, sampler=DistributedSampler(dataset) )def main(save_every: int, total_epochs: int, batch_size: int, snapshot_path: str = &quot;snapshot.pt&quot;): ddp_setup() dataset, model, optimizer = load_train_objs() train_data = prepare_dataloader(dataset, batch_size) trainer = Trainer(model, train_data, optimizer, save_every, snapshot_path) trainer.train(total_epochs) destroy_process_group()if __name__ == &quot;__main__&quot;: import argparse parser = argparse.ArgumentParser(description=&#x27;simple distributed training job&#x27;) parser.add_argument(&#x27;total_epochs&#x27;, type=int, help=&#x27;Total epochs to train the model&#x27;) parser.add_argument(&#x27;save_every&#x27;, type=int, help=&#x27;How often to save a snapshot&#x27;) parser.add_argument(&#x27;--batch_size&#x27;, default=32, type=int, help=&#x27;Input batch size on each device (default: 32)&#x27;) args = parser.parse_args() main(args.save_every, args.total_epochs, args.batch_size) 方案一: 在每台节点上手动单独运行 torchrun 命令 12345678# 节点1torchrun \--proc_per_node=4 \ # 这里的数字取决于每个节点上的 GPU 数量, 在不同的节点上的 GPU 数量可能不同--nnodes=2 \ # 节点总数--node_rank=0 \ # 当前节点编号--rdzv_id=456 \ # renderzvous 会合节点ID, 各节点相同--rdzv_endpoint=172.31.43.139:29603 \ # 会合节点的IP:端口, 各节点相同multinode_torchrun.py 50 10 12345678# 节点2torchrun \--proc_per_node=2 \ # 当前节点只有 2 个 GPU--nnodes=2 \ # 节点总数--node_rank=1 \ # 当前节点编号--rdzv_id=456 \ # renderzvous 会合节点ID, 各节点相同--rdzv_endpoint=172.31.43.139:29603 \ # 会合节点的IP:端口, 各节点相同multinode_torchrun.py 50 10 方案二: 创建集群, 使用调度器 不同云服务商有不同的创建集群的方法 创建 slurm 脚本 1234567891011121314151617181920212223#!/bin/bash#SBATCH --job-name=multinode-example#SBATCH --nodes=4#SBATCH --ntasks=4#SBATCH --gpus-per-task=1#SBATCH --cpus-per-task=4 # 多个 CPU 可以让数据加载变快一些nodes=( $( scontrol show hostnames $SLURM_JOB_NODELIST ) )nodes_array=($nodes)head_node=$&#123;nodes_array[0]&#125;head_node_ip=$(srun --nodes=1 --ntasks=1 -w &quot;$head_node&quot; hostname --ip-address)echo Node IP: $head_node_ipexport LOGLEVEL=INFOsrun torchrun \--nnodes 4 \--nproc_per_node 1 \--rdzv_id $RANDOM \--rdzv_backend c10d \--rdzv_endpoint $head_node_ip:29500 /shared/examples/multinode_torchrun.py 50 10 运行脚本开始训练 1sbatch slurm/sbatch_run.sh 可使用 squeue 命令查看任务队列 使用 DDP 模式单机多卡或多机多卡训练 minGPT 的示例 DDP 的实现原理: 给模型的参数注册钩子, 在反向传播时, 将梯度同步到所有进程, 以便所有进程对应的模型的参数梯度值达成最终一致性, 这样各个进程在更新参数后的模型状态能够保持一致. 处理速度差异 不同的进程的计算进度通常有先有后, 在数据同步时, 不同进程之间需要相互等待, 确保所有分片的数据完成同步后, 再进行下一步的计算. 因此需要设置一个足够大的 timeout 值, 避免有些进程在等待的过程中出现超时. torch.distributed 库中有个 barrier() 方法可用来设置集合点, 确保所有进程到达该集合点后, 再进入下一步. 这样可以避免 A 进程还未保存模型数据, B 进程已经先加载数据并往下计算. 结合模型并行 Model Parallelism, 将模型的不同层放在不同的 GPU 上面, 不同 GPU 组成流水线； 1234567891011121314class ToyMpModel(nn.Module): def __init__(self, dev0, dev1): # 参数是两个 GPU super(ToyMpModel, self).__init__() self.dev0 = dev0 self.dev1 = dev1 self.net1 = torch.nn.Linear(10, 10).to(dev0) # 线性层1 在 dev0 self.relu = torch.nn.ReLU() self.net2 = torch.nn.Linear(10, 5).to(dev1) # 线性层2 在 dev1 def forward(self, x): x = x.to(self.dev0) # 复制输入到 dev0 x = self.relu(self.net1(x)) x = x.to(self.dev1) # 复制上一层的输出到 dev1 return self.net2(x) 模型并行有几种不同类型: Tensor Paralelism, 张量并行 Pipeline Paralelism, 流水线并行 Expert Parallelism, 专家并行 Uneven Inputs 不同的 GPU 进程可能收到的 batch 大小不同, 出现不均衡的输入, 会导致不同的进程的迭代次数不一样. 此时某些进程可能提前完成计算, 但其他进程可能还在训练中. 如果让完成计算的进程退出, 会导致后续同步数据时, 其他进程一直处理等待的状态, 最终造成死锁. 为避免这个问题 torch.distributed.algorithms.join 库中引入了 Join 上下文管理器. 当某些进程提前完成数据的计算后, 会进入 join 模式. 在这个模式下, 该进程不会提前退出, 而是会假装仍在工作, 会继续参与数据同步的工作, 只是它发的梯度数据是零, 同时在 step 时也不会更新模型的参数. 直到所有进程都完成计算后, 整个上下文才会终止. 12345678910111213141516171819202122232425262728293031323334import osimport torchimport torch.distributed as distimport torch.multiprocessing as mpfrom torch.distributed.algorithms.join import Joinfrom torch.nn.parallel import DistributedDataParallel as DDPBACKEND = &quot;nccl&quot;WORLD_SIZE = 2NUM_INPUTS = 5def worker(rank): os.environ[&#x27;MASTER_ADDR&#x27;] = &#x27;localhost&#x27; os.environ[&#x27;MASTER_PORT&#x27;] = &#x27;29500&#x27; dist.init_process_group(BACKEND, rank=rank, world_size=WORLD_SIZE) model = DDP(torch.nn.Linear(1, 1).to(rank), device_ids=[rank]) # Rank 1 比 rank 0 多一个输入, 模拟输入不平衡的场景 inputs = [torch.tensor([1]).float() for _ in range(NUM_INPUTS + rank)] num_inputs = 0 with Join([model]): # 使用 Join 管理上下文 for input in inputs: num_inputs += 1 loss = model(input).sum() loss.backward() print(f&quot;Rank &#123;rank&#125; has exhausted all &#123;num_inputs&#125; of its inputs!&quot;)def main(): mp.spawn(worker, nprocs=WORLD_SIZE, join=True)if __name__ == &quot;__main__&quot;: main() Join 还可以同时管理多个类, 例如 ZeroRedundancyOptimizer, 示例如下: ZeroRedundancyOptimizer 用来给优化器状态进行分片, 这样优化器的数据也可以像梯度一样是分布式的, 好处是可以减少单个 GPU 的内存占用, 等实际需要使用时, 多个 GPU 之间再进行同步即可. 缺点是需要付出一点数据同步的时间. 以时间换空间, 是否使用要看用哪种优化器, 有些优化器的状态占内存较多, 例如 Adam. 有些则没有； 12345678910111213141516171819202122from torch.distributed.optim import ZeroRedundancyOptimizer as ZeROfrom torch.optim import Adamdef worker(rank): os.environ[&#x27;MASTER_ADDR&#x27;] = &#x27;localhost&#x27; os.environ[&#x27;MASTER_PORT&#x27;] = &#x27;29500&#x27; dist.init_process_group(BACKEND, rank=rank, world_size=WORLD_SIZE) model = DDP(torch.nn.Linear(1, 1).to(rank), device_ids=[rank]) optim = ZeRO(model.parameters(), Adam, lr=0.01) # 使用 ZeroRedundancyOptimizer # Rank 1 比 rank 0 多一个输入, 模拟输入不平衡的场景 inputs = [torch.tensor([1]).float() for _ in range(NUM_INPUTS + rank)] num_inputs = 0 with Join([model, optim]): # 优化器和模型一起 Join for input in inputs: num_inputs += 1 loss = model(input).sum() loss.backward() optim.step() print(f&quot;Rank &#123;rank&#125; has exhausted all &#123;num_inputs&#125; of its inputs!&quot;) Join 支持传入一些参数 1234# 传入 divide_by_initial_world_size 参数with Join([model, optim], divide_by_initial_world_size=False): for input in inputs: ... FSDP2 Fully Sharded Data Parallel, 全分片数据并行. DDP 只是训练数据分片, FSDP 则更进一步, 连模型参数, 优化器状态都进行分片, 这样做的好处是可以减少单个 GPU 的内存容量要求. 由于 FSDP 将模型的参数也分片了, 因此相比 DDP, 它不仅要同步梯度, 还多了一个同步参数的动作. 即每个 GPU 需要先all-gather 动态的收集其他 GPU 上面的参数, 基于完整的模型参数计算出结果后, 再释放掉内存, 只保留自己所负责的那部分参数. 所以从结果上来看, 每个 GPU 上面的模型参数好像是完整的, 但实际上这种完整是一种临时拼凑的状态，是一种逻辑上的完整，而不是物理上的完整. 计算结束后, 实际保存的仍然只是一个参数分片. FSDP 或许可视为一种更加激进的分片策略, 通过极致的以时间换空间, 进一步压榨 GPU 显存 模型初始化 123456789101112131415161718from torch.distributed.fsdp import fully_shard, FSDPModulemodel = Transformer()for layer in model.layers: fully_shard(layer) # 模型的每一层都要 fully_shard 进行分片 fully_shard(model) # 最后模型也要分片 fully_shardassert isinstance(model, Transformer)assert isinstance(model, FSDPModule)print(model)# FSDPTransformer(# (tok_embeddings): Embedding(...)# ...# (layers): 3 x FSDPTransformerBlock(...)# (output): Linear(...)# ) fully_shard 会将模型的参数由 Tensor 转成 DTensor 类型(一种数据抽象), 用来表示它是做了分片的参数. DTensor 有助于简化各项操作的逻辑, 减少手动处理这些分片数据的同步工作. FSDP2 在参数的第一个维度上进行分片, 因此第一维的数量需要是 world size 的倍数, 否则无法均匀分片. 此时 FSDP 默认会报错. 由于 FSDP2 模式下参数是分片的, 因此在保存模型时, 可以借助 DCP（Distributed Checkpointing）实现分布式保存. 每个 GPU 进程只保存自己的那部分参数, 这样可以减少通讯成本. 后续加载参数时, 每个 GPU 也可以只加载自己负责的那部分参数. 前向/后向预取 由于模型参数是分片, 计算前需要实时 all-gather 聚合, 这样就涉及了通信的时间. 理想情况下让计算和通信同时进行, 这样计算的时候,不用等待通信. 有两种实现的方案: 隐式预取: 在计算当前层的时候, 后台自动偷偷 all-gather 预取下一个 layer 或 block 所需的参数. 显式预取: 手动控制什么时候预取参数, 好处是非常灵活, 一般有以下几种使用场景: 隐式只预取一层, 显式则可以预取多层, 好处是减少等待的发生, 缺点是占用多一些内存空间； 预热: 在调用 model(x) 之前先预取, 这样调用 model 后直接开算, 不用等待； CPU 工作负载过高, 没有及时发出预取指令, 造成空闲等待, 因此只能手动完成； 以下是隐式预取的图示: 以下是显式预取的代码示例: 12345678910111213141516171819202122232425num_to_forward_prefetch = 2for i, layer in enumerate(model.layers): if i &gt;= len(model.layers) - num_to_forward_prefetch: break layers_to_prefetch = [ model.layers[i + j] for j in range(1, num_to_forward_prefetch + 1) ] layer.set_modules_to_forward_prefetch(layers_to_prefetch) # 前向预取num_to_backward_prefetch = 2for i, layer in enumerate(model.layers): if i &lt; num_to_backward_prefetch: continue layers_to_prefetch = [ model.layers[i - j] for j in range(1, num_to_backward_prefetch + 1) ] layer.set_modules_to_backward_prefetch(layers_to_prefetch) # 后向预取for _ in range(epochs): model.unshard() # 手动触发一次 all-gather, 减少后续 GPU 的等待时间, 正常 unshard 是隐式触发的 x = torch.randint(0, vocab_size, (batch_size, seq_len), device=device) loss = model(x).sum() loss.backward() optim.step() optim.zero_grad() 开启混合精度 FSDP2 支持灵活的混合精度策略, 以便提高训练的速度. 典型用法示例: 在前向和后向传播将默认的 float32 转成 bfloat16 类型, 这样可以节省显存占用； 做梯度聚合时, 将 bfloat16 类型转回 float32, 以便提高梯度计算的精度, 避免误差可能带来的发散； 123456789101112131415161718192021222324252627model = Transformer(model_args)# 混合精度策略fsdp_kwargs = &#123; &quot;mp_policy&quot;: MixedPrecisionPolicy( param_dtype=torch.bfloat16, # 参数用 bfloat16 reduce_dtype=torch.float32, # 梯度聚合用 float32 )&#125;for layer in model.layers: fully_shard(layer, **fsdp_kwargs) # 传递策略参数fully_shard(model, **fsdp_kwargs) # 传递策略参数# sharded parameters are float32for param in model.parameters(): assert param.dtype == torch.float32# unsharded parameters are bfloat16model.unshard()for param in model.parameters(recurse=False): assert param.dtype == torch.bfloat16model.reshard()# 优化器使用默认的 float32optim = torch.optim.Adam(model.parameters(), lr=1e-2)# training loop# ... 梯度裁剪与基于 DTensor 的优化器 在 full_shard 模型后, 再初始化优化器, 以便优化器能够正确跟踪分布在不同 GPU 上面的参数分片. 参数分片后的包装类型是 DTensor, 它默认支持梯度裁剪. 梯度裁剪涉及计算范数, 此时需要先聚合梯度. DTensor 会自动拦截各种张量 Tensor 的正常操作, 然后在需要时会自动完成通信聚合的相关工作, 对用户来说是透明的. TP 工作原理 对张量进行拆分计算的示意图, 例如 MLP 和自注意力两种计算场景: TP 的工作原理主要由三部分构成: 静态分片 模型初始化时, TP 为模型的每一层选择不同的并行策略(按行或按列) 调用 parallelize_module 将模型转换为并行版本； 将普通张量 Tensor 转换为支持并行的 DTensor 张量(自动处理跨设备的通信) 动态通信 all-reduce all-gather reduce-scatter 局部计算: 每个 GPU 只负责计算自己负责的那部分分片数据； 使用场景 虽然 FSDP 已经能够实现数据并行, 也能够对模型参数进行切片, 但它仍然面临一些瓶颈: 当 GPU 数量变多时, 通信成本变成瓶颈； 每个 GPU 的 batch size 最小为 1, 过多的 GPU 导致总体 batch size 非常大. 但过大的 batch size 可能导致收敛不稳定； 较小的 batth size 有可能无法满足 GPU 的形状规整要求(例如维度是 8, 16, 32 的倍数), 导致浮点运算的效率不高； TP/SP 刚好可以用来解决以上问题: 在节点间使用 FSDP, 单节点内部的多 GPU 之间使用 TP, 这样可以显著减少通信成本. 例如一机八卡, 那么节点间的通信成本可以除以 8 倍；相当于 FSDP 是以节点进行切片, 而不是以 GPU 进行切片； 张量支持切片后, GPU 的 batch size 就可以小于 1 了, 二者实现了解耦； 张量切片有助于满足 GPU 浮点运算对矩阵形状的规整要求； 问题 解决方案 效果 FSDP 在超大规模 GPU 下通信开销大 节点内用 TP/SP，节点间用 FSDP 减少 FSDP 通信域，降低延迟 数据并行受批大小限制 引入 TP/SP 解耦 GPU 数与批大小 可继续增加 GPU 而不破坏收敛 小 batch 导致计算效率低 TP/SP 优化矩阵形状 提高 FLOPS 利用率 使用方法 1234# 初始化一个 device emshfrom torch.distributed.device_mesh import init_device_meshtp_mesh = init_device_mesh(&quot;cuda&quot;, (8,)) 如何实施张量并行, 取决于模型某一层如何进行计算, 因此要视具体情况而定, 举例如下: 123# 假设有如下的 SwiGLU 激活运算, 来源于 Transformer block 的 feed_forward 层def forward(self, x): return self.w2(F.silu(self.w1(x)) * self.w3(x)) w1 和 w3 是两个线性层, 是可以并行的矩阵乘法运算, w2 同样是线性层, 基于前二者的逐元素相乘的结果再做矩阵乘法； 第1步: w1 和 w3 是单独对输入 x 做矩阵乘法, 因此二者可以按列切片, 这样每个 GPU 只需计算自己负责的那一部分列即可；x 则需要完整的广播到所有 GPU, 没有切片； 第2步: w1 和 w3 是逐元素相乘, 因此前面的计算结果仍然可以在 GPU 内部做局部计算, 无须和其他 GPU 进行通信； 第3步: w2 是矩阵乘法, 可将 w2 按行切分, 每个 GPU 单独计算出一部分结果, 最后通过 all reduce 聚合成完整的结果； 12345678# 制定如下的并行策略from torch.distributed.tensor.parallel import ColwiseParallel, RowwiseParallel, parallelize_modulelayer_tp_plan = &#123; &quot;feed_foward.w1&quot;: ColwiseParallel(), &quot;feed_forward.w2&quot;: RowwiseParallel(), &quot;feed_forward.w3&quot;: ColwiseParallel(),&#125; 组件 并行方式 输入布局 输出布局 是否需要通信 w1, w3 Column-wise Replicated Sharded 否（各自独立计算） w1(x) * w3(x) Element-wise Sharded Sharded 否（同设备上直接相乘） w2 Row-wise Sharded Replicated（经 all-reduce） 是（最后一次 all-reduce） 以上示例是 feed_forward 层, 对于 Transformer 模块中的 self attention 注意力层, 并行策略大概类似: 12345678910111213layer_tp_plan = &#123; # q,k,v 按列切分 # use_local_output=False 确保输出仍为 DTensor, 而不是普通 tensor, 保留分片信息, 非常重要!!! &quot;attention.wq&quot;: ColwiseParallel(use_local_output=False), &quot;attention.wk&quot;: ColwiseParallel(use_local_output=False), &quot;attention.wv&quot;: ColwiseParallel(use_local_output=False), # o 按行切分 &quot;attention.wo&quot;: RowwiseParallel(), # 以下是 feed_forward 层 &quot;feed_forward.w1&quot;: ColwiseParallel(), &quot;feed_forward.w2&quot;: RowwiseParallel(), &quot;feed_forward.w3&quot;: ColwiseParallel(),&#125; 使用 parallel_module 函数将 transformer block 转换成张量并行模式 12345678for layer_id, transformer_block in enumerate(model.layers): layer_tp_plan = &#123;...&#125; # 详见前面的示例, 此处内容略 parallelize_module( module=transformer_block, device_mesh=tp_mesh, parallelize_plan=layer_tp_plan, ) 对于模型头部的 Embedding 层和尾部的 Linear 层, 采用类似的张量并行策略 1234567891011121314model = parallelize_module( model, tp_mesh, &#123; # 嵌入层按行分片, 将 vocal 词汇表切分到不同的设备上 # 也可按列分, 或者不分(不分最简单, 除非特别大) &quot;tok_embeddings&quot;: RowwiseParallel( input_layouts=Replicate(), # 输入的 token ids 是全量副本, 不分片 ), &quot;output&quot;: ColwiseParallel( output_layouts=Replicate(),# 输出是一个拼接后的完整副本, 为了方便后续计算 loss ), &#125;) 用于归一化层 SP(sequence parallel, 序列并行), 是 TP 张量并行的一个变体. TP 是对权重进行切分, 比如按矩阵的行或列. 而 SP 则更进一步, 对输入序列的长度进行切分. 它主要用于 LayerNorm 或者 RMSNorm 等归一化层中, 将一个长序列切分成多个片段, 每个 GPU 负责处理其中一个片段. 目的是为了减少激活值所占用的内存. 因为激活值会随着输入序列的长度和批量大小呈线性增长. SP: Shard(1), 在第1维(seq维)进行切分, [batch, seq_len, hidden_dim] 变成 [batch, seq_len / N, hidden_dim] RMSNorm 或 LayerNorm 等归一化层是在 hiddem_dim 维度上做归一化, 与 sequence 维度无关, 因此归一化层很适合用来分片, 不同分片之间无需通信. 而 Attention 或 FeedForward 则不适合用来做 SP, 因为它们的矩阵需要完整的行或列, SP 后会带来很大的通信成本. 代码示例如下: 12345678910111213141516171819202122232425from torch.distributed.tensor.parallel import ( PrepareModuleInput, SequenceParallel,)layer_tp_plan = &#123; # 当使用 SP 分片, 输出有可能需要转回 Replicate, 以供后续的层使用 &quot;attention_norm&quot;: SequenceParallel(), # SP 分片 &quot;attention&quot;: PrepareModuleInput( input_layouts=(Shard(1), Replicate()), # 需要将 Shard(1) 转回 Replicate desired_input_layouts=(Replicate(), Replicate()), # 期望的输入格式 ), &quot;attention.wq&quot;: ColwiseParallel(use_local_output=False), &quot;attention.wk&quot;: ColwiseParallel(use_local_output=False), &quot;attention.wv&quot;: ColwiseParallel(use_local_output=False), &quot;attention.wo&quot;: RowwiseParallel(output_layouts=Shard(1)), &quot;ffn_norm&quot;: SequenceParallel(), # SP 分片 &quot;feed_forward&quot;: PrepareModuleInput( input_layouts=(Shard(1),), # 需要将 Shard(1) 转回 Replicate desired_input_layouts=(Replicate(),), # 期望的输入格式 ), &quot;feed_forward.w1&quot;: ColwiseParallel(), &quot;feed_forward.w2&quot;: RowwiseParallel(output_layouts=Shard(1)), &quot;feed_forward.w3&quot;: ColwiseParallel(),&#125; 12345678910111213141516# 处理头尾的层model = parallelize_module( model, tp_mesh, &#123; &quot;tok_embeddings&quot;: RowwiseParallel(嵌入层 input_layouts=Replicate(), output_layouts=Shard(1), # 将输出转成 SP 的 Shard(1) ), &quot;norm&quot;: SequenceParallel(), &quot;output&quot;: ColwiseParallel( input_layouts=Shard(1), output_layouts=Replicate() # 输出转成 Replicate ), &#125;) 损失并行 如果 vocal_size 已经是分片的, 那么在计算损失时, 每个 GPU 也可先做自己负责的 logits 的局部交叉熵损失计算, 之后再 reduce 得到最终的 loss； 1234# 使用 loss_parallel() 上下文管理器, cross_entropy 会自动按分片做损失的并行计算with loss_parallel(): loss = torch.nn.functional.cross_entropy(logits, labels) loss.backward() # 需要在上下文中调用 12345678910111213141516model = parallelize_module( model, tp_mesh, &#123; &quot;tok_embeddings&quot;: RowwiseParallel( input_layouts=Replicate(), output_layouts=Shard(1), ), &quot;norm&quot;: SequenceParallel(), &quot;output&quot;: ColwiseParallel( input_layouts=Shard(1), # 输出是 DTensor, 不再是 Replicate, 以便能够实现 loss parallel use_local_output=False, ), &#125;,) 结合 FSDP FSDP 负责节点间的切片, TP 负责单节点多个 GPU 间的切片 以上切分方式可通过设置 DeviceMesh 的参数来实现 1234567891011121314151617from torch.distributed.device_mesh import init_device_meshfrom torch.distributed.tensor.parallel import ColwiseParallel, RowwiseParallel, parallelize_modulefrom torch.distributed.fsdp import fully_shard# 2d mesh 网格, 8路 DP, 8路 TP, 总共 64 个 GPUmesh_2d = init_device_mesh(&quot;cuda&quot;, (8, 8))tp_mesh = mesh_2d[&quot;tp&quot;] # 单节点内部的子网格dp_mesh = mesh_2d[&quot;dp&quot;] # 跨节点的子网格model = Model(...)tp_plan = &#123;...&#125;# 先在节点内部启用张量并行model_tp = parallelize_module(model, tp_mesh, tp_plan)# 再在节点间启用 FSDP 数据并行model_2d = fully_shard(model_tp, mesh=dp_mesh, ...) 使用 FSDP + TP 的代码示例 DeviceMesh DeviceMesh 是用来管理进程组的一个高级抽象, 简化手动管理这些进程的工作, 例如给每个进程分配 rank id 12345678# DeviceMesh 让创建多维并行变得很简单, 以下是创建二维并行的示例# 无须再手工创建 replicate group 和 shard groupfrom torch.distributed.device_mesh import init_device_meshmesh_2d = init_device_mesh(&quot;cuda&quot;, (2, 4), mesh_dim_names=(&quot;replicate&quot;, &quot;shard&quot;))# Users can access the underlying process group thru `get_group` API.replicate_group = mesh_2d.get_group(mesh_dim=&quot;replicate&quot;)shard_group = mesh_2d.get_group(mesh_dim=&quot;shard&quot;) HSDP HSDP, Hybrid Sharding Data Paralelism, 混合数据并行, 单节点内部使用 FSDP, 多节点之间使用 DDP 1234567891011121314151617181920212223import torchimport torch.nn as nnfrom torch.distributed.device_mesh import init_device_meshfrom torch.distributed.fsdp import fully_shard as FSDPclass ToyModel(nn.Module): def __init__(self): super(ToyModel, self).__init__() self.net1 = nn.Linear(10, 10) self.relu = nn.ReLU() self.net2 = nn.Linear(10, 5) def forward(self, x): return self.net2(self.relu(self.net1(x)))# HSDP: MeshShape(2, 4)mesh_2d = init_device_mesh(&quot;cuda&quot;, (2, 4), mesh_dim_names=(&quot;dp_replicate&quot;, &quot;dp_shard&quot;))model = FSDP( ToyModel(), device_mesh=mesh_2d) 自定义并行方案 对于复杂的自定义并行方案, DeviceMesh 支持从网格中提取子网格, 进行一些自定义的操作 12345678910111213from torch.distributed.device_mesh import init_device_mesh# 定义一个三维并行的网格mesh_3d = init_device_mesh(&quot;cuda&quot;, (2, 2, 2), mesh_dim_names=(&quot;replicate&quot;, &quot;shard&quot;, &quot;tp&quot;))# 提取子网格hsdp_mesh = mesh_3d[&quot;replicate&quot;, &quot;shard&quot;]tp_mesh = mesh_3d[&quot;tp&quot;]# 提取进程组replicate_group = hsdp_mesh[&quot;replicate&quot;].get_group()shard_group = hsdp_mesh[&quot;shard&quot;].get_group()tp_group = tp_mesh.get_group() PP Pipeline Paralism, 流水线并行. 当模型太大, 无法放入单个 GPU 时, 可考虑使用 PP 并行模式. 将模型按层或模块拆分为多个 stage, 每个 GPU 负责一部分 stage；同时将一个 batch 的数据, 也拆分成多个小的 micro-batch, 逐个输入流水线. micro-batch 的好处是小步快跑,这样有助于让多个 stage 同时跑起来；如果没有拆分, 则后面的 stage 需要等待前面的 stage 处理完；尽管如此, 启动和结束时出现一个小的等待窗口仍然是不可避免的, 称为 bubble； 执行顺序如下（时间步 t1, t2, …）： 时间 S1（设备0） S2（设备1） t1 M1 前向 —— t2 M2 前向 M1 前向 + 反向 t3 M3 前向 M2 前向 + 反向 t4 M4 前向 M3 前向 + 反向 t5 —— M4 前向 + 反向

第1章 初识 GPT-4 LLM 概述 探索语言模型和 NLP 的基础 GPT-4 和 ChatGPT 基于一种特定的神经网络架构 Transformer； Transformer 通过关注句子和段落的不同部分，学习到句子中各个单词的模式和关系，从而能够理解上下文；因此，Transformer 很擅长语言翻译、问题回答和文本生成类的任务； 最早的语言模型是 n-gram，它的原理很简单，就是统计各个单词之间按顺序出现的概率。当给出 A 单词时，它根据概率预测下一个单词 B； 为了提高 n-gram 的性能，之后引入了循环神经网络（RNN，recurrent neural networ）和长短期记忆（LSTM，long short term memory）的方法，以便模型能够更好的理解上下文； 理解 Transformer 在处理短文本时，RNN 效果还行，但如果是长文本，上下文很大，超过了 RNN 的处理能力，容易出现上下文遗忘的问题； Transformer 通过使用注意力机制，解决了 RNN 面临的问题；所谓的注意力机制，即模型不再将所有单词视为同等重要，而是只关注其中少数几个关键词，这样既降低了数据处理的负担，又提高了准确性； 注意力机制有两个模块，分别为： 交叉注意力：输入与输出的相关性匹配；（关注重点） 自注意力：区分输入的不同部分之间的相对重要性；（分清主次） 自注意力机制给句子中的不同单词分配不同的权重后，有助于抓出核心单词，构建新的抽象概念； 解密 GPT 模型的标记化和预测步骤 文本补全：接受一段输入（提示词），生成一段输出； Transformer 架构使得模型能够识别关键信息和上下文；它在生成预测时，也用到了迭代机制，即先预测下一个最有可能出现的词，之后基于包含预测词的新句子，再次预测下一个可能出现的词。不断迭代重复这个过程，直到生成整个完整的句子； GPT 模型简史 早期的 NLP 模型是监督式的，用于分类预测，需要使用标注数据进行训练，但标注的成本很高，难以获得大规模的训练数据；GPT 则是无监督式的，突破了这个限制，模型参数的数量也因此急剧膨胀； 基于预测的工作模式，并不能满足大部分使用场景，因此 GPT3 引入了微调和反馈，即使用提示词让模型根据反馈再次学习，从而得出更准确的结果； 所谓的微调和反馈，即人工编写一个示例打个样，然后做为训练数据，让模型学习； 微调的三个步骤： 制作示例，训练模型 基于相同问题，设置不同的随机数（temperature），以便模型输出多个不同的结果，然后给结果打分； 基于打分结果，设置奖励机制，再次训练模型； 案例 Be My Ayes：作为盲人的虚拟助手，帮助他们获得视觉信息； 摩根士丹利：从公司报告库中，快速检索文本，以获得答案； 可汗学院：生成虚拟的教学助手，回答学生的提问，并给予鼓励； 多邻国：通过角色扮演，让学生获得沉浸式的学习氛围 Yabble：分析消费者的数据，提供见解，辅助决策； Waymark：快速生成视频脚本，提高视频制作人员的效率； Inworld AI：生成有趣、有独特性格特点的游戏角色，提高游戏开发效率； AI 幻觉 模型很适合用来处理创意型的任务，因为这些任务并没有标准答案。但目前还不太适合用来生成严肃问题的答案，例如医学诊断等；因为这些任务的准确性要求很高，而且 AI 的本质上是预测，因此有时候它提供的答案并不正确，却对错误答案信誓旦旦，有可能会误导提问者； 使用插件和微调优化 GPT 模型 使用插件能够让 GPT 能够更好的处理特定任务； 第2章 深入了解 API 基本概念 针对不同的使用场景，OpenAI 提供了不同的模型，几种场景包括： 聊天 助手 补全 文本转语音 OpenAI 的模型 InstructGPT ChatGPT GPT-4 使用 GPT 模型 预设提示词的使用示例，每个示例提供了一些特定的自定义参数； OpenAI 既可以使用 GUI 来调用，也可以通过 API 来调用； 1234567891011import openaiopenai.api_key = os.getenv(&quot;OPENAI_API_KEY&quot;)response = openai.Completion.create( model=&quot;text-davinci-003&quot;, prompt=&quot;As Descartes said, I think therefore&quot;, temperature=0.7, max_tokens=3, top_p=1, frequency_penalty=0, presence_penalty=0,) OpenAI Python 123456789101112131415161718192021import openai#对GPT-3.5 Turbo来说，端点是ChatCompletionopenai.ChatCompletion.create( #对GPT-3.5 Turbo来说，模型是gpt-3.5-turbo model=&quot;gpt-3.5-turbo&quot;, #消息列表形式的对话 messages=[ &#123;&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: &quot;You are a helpful teacher.&quot;&#125;, &#123; &quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;Are there other measures than time \ complexity for an algorithm?&quot;, &#125;, &#123; &quot;role&quot;: &quot;assistant&quot;, &quot;content&quot;: &quot;Yes, there are other measures besides time \ complexity for an algorithm, such as space complexity.&quot;, &#125;, &#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;What is it?&quot;&#125;, ],) 每次调用 API 时，都需要附带整个对话记录，因为模型并不记忆上下文，所以需要在请求中携带上下文； 从文本补全到函数 以下示例通过文字描述想要查询的目标，由 GPT 转成 SQL 语句，然后调用预设好的函数，执行该 SQL 语句；得到数据库的查询结果后，再发给 GPT，转换成普遍人能够读懂的结果（用文字来描述查询结果）； 1234567# 示例函数（有点像 JS 里面的回调函数）def find_product(sql_query): results = [ &#123;&quot;name&quot;: &quot;pen&quot;, &quot;color&quot;: &quot;blue&quot;, &quot;price&quot;: 1.99&#125;, &#123;&quot;name&quot;: &quot;pen&quot;, &quot;color&quot;: &quot;red&quot;, &quot;price&quot;: 1.78&#125;, ] return results 1234567891011121314151617# 函数定义functions = [ &#123; &quot;name&quot;: &quot;find_product&quot;, &quot;description&quot;: &quot;Get a list of products from a sql query&quot;, &quot;parameters&quot;: &#123; &quot;type&quot;: &quot;object&quot;, &quot;properties&quot;: &#123; &quot;sql_query&quot;: &#123; &quot;type&quot;: &quot;string&quot;, &quot;description&quot;: &quot;A SQL query&quot;, &#125; &#125;, &quot;required&quot;: [&quot;sql_query&quot;], &#125;, &#125;] 12345678910111213141516171819#示例问题user_question = &quot;I need the top 2 products where the price is less than 2.00&quot;messages = [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: user_question&#125;]#使用函数定义调用ChatCompletion端点response = openai.ChatCompletion.create( model=&quot;gpt-3.5-turbo-0613&quot;, messages=messages, functions=functions)response_message = response[&quot;choices&quot;][0][&quot;message&quot;]messages.append(response_message)&#x27;&#x27;&#x27;&quot;function_call&quot;: &#123; &quot;name&quot;: &quot;find_product&quot;, &quot;arguments&quot;: &#x27;&#123;
 &quot;sql_query&quot;: &quot;SELECT * FROM products \ WHERE price &lt; 2.00 ORDER BY price ASC LIMIT 2&quot;
&#125;&#x27;,&#125;&#x27;&#x27;&#x27; 123456789101112131415161718#调用函数function_args = json.loads( response_message[&quot;function_call&quot;][&quot;arguments&quot;])products = find_product(function_args.get(&quot;sql_query&quot;))#将函数的响应附加到消息中messages.append( &#123; &quot;role&quot;: &quot;function&quot;, &quot;name&quot;: function_name, &quot;content&quot;: json.dumps(products), &#125;)#将函数的响应格式化为自然语言response = openai.ChatCompletion.create( model=&quot;gpt-3.5-turbo-0613&quot;, messages=messages,) 基于聊天模型的输入，必须使用对话格式；而补全模型的输入则可以是单独的提示词； 其他 API 功能 嵌入 将不是数值类型的元素，转换成数值向量；嵌入有个突出的特点，即它将数据转换成数值格式后，这些数值之间仍然保持语义相似性；即含义相近的词，在数值空间的距离也更近； 嵌入在 LLM 中用得非常广泛，一般使用 512 维来表示，这使得模型能够存储复杂的关系； 内容审核模型 为了确保用户输入的提示词，符合法律规定，OpenAI 还部署了一个内容审核模型，以确保用户的输入合法； Whipser 和 DALL-E Whipser 用于语音识别、翻译等场景； DALL-E 则能够根据自然语言的描述，生成图片； 第3章 构建应用程序 应用程序开发概述 从环境变量读取密钥 软件架构设计原则 OpenAPI 的接口很可能会更新，因此有必要在前端与 OpenAI 之间增加一层抽象，以便将前端和 OpenAI 之间进行解耦 LLM 驱动型应用程序的漏洞 由于用户的输入存在不可控的因素，因此有必要采取措施，对输入进行检查，否则有可能会发生注入攻击； 示例项目 新闻稿生成器 根据某个事实发生的事件，生成新闻稿； 123456789101112131415161718192021222324import openaidef ask_chatgpt(messages): response = openai.ChatCompletion.create( model=&quot;gpt-3.5-turbo&quot;, messages=messages ) return response[&quot;choices&quot;][0][&quot;message&quot;][&quot;content&quot;]prompt_role = &quot;You are an assistant for journalists. \ Your task is to write articles, based on the FACTS that are given to you. \ You should respect the instructions: the TONE, the LENGTH, \ and the STYLE&quot;from typing import Listdef assist_journalist( facts: List[str], tone: str, length_words: int, style: str): facts = &quot;, &quot;.join(facts) prompt = f&quot;&#123;prompt_role&#125; \ FACTS: &#123;facts&#125; \ TONE: &#123;tone&#125; \ LENGTH: &#123;length_words&#125; words \ STYLE: &#123;style&#125;&quot; return ask_chatgpt([&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: prompt&#125;]) 1234567# 测试print( assist_journalist( [&quot;The sky is blue&quot;, &quot;The grass is green&quot;], &quot;informal&quot;, \ 100, &quot;blogpost&quot; )) 123456789101112131415# 生成结果&quot;Hey, everyone! Did you know that the sky is blue and the grass is green?I mean, it&#x27;s something we see every day and probably take for granted,but it&#x27;s still pretty amazing if you think about it! The sky appearsblue to us because of something called Rayleigh scattering – basically,the molecules in the Earth&#x27;s atmosphere scatter sunlight in all differentdirections. Blue light has a shorter wavelength, so it gets scatteredmore than the other colors in the spectrum. That&#x27;s why the sky looksblue most of the time! As for the grass being green... that&#x27;s due tochlorophyll, the pigment that helps plants capture sunlight to maketheir food. Chlorophyll absorbs red and blue light, but reflectsgreen light, which is why we see plants as green.It&#x27;s pretty cool how science explains these things we take for granted,don&#x27;t you think? Next time you&#x27;re outside, take a moment to appreciatethe color palette around you!&quot; Youtube 视频摘要 1234567891011121314151617import openai#从文件中读取文字记录with open(&quot;transcript.txt&quot;, &quot;r&quot;) as f:transcript = f.read()#调用ChatCompletion端点，并使用gpt-3.5-turbo模型response = openai.ChatCompletion.create( model=&quot;gpt-3.5-turbo&quot;, messages=[ &#123;&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: &quot;You are a helpful assistant.&quot;&#125;, &#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;Summarize the following text&quot;&#125;, &#123;&quot;role&quot;: &quot;assistant&quot;, &quot;content&quot;: &quot;Yes.&quot;&#125;, &#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: transcript&#125;, ],)print(response[&quot;choices&quot;][0][&quot;message&quot;][&quot;content&quot;]) 如果视频脚本很长，超过了 API 字数上限的话，那么可以考虑将脚本分成多个段落，每个段落生成一份小摘要，最后再汇总小摘要，生成一份大摘要； 打造游戏专家 目标：构建一个 AI 助手，它能够根据任天堂的操作指南，回答用户关于《塞尔达传说》的相关问题； 有两种常见的微调模型的方法 基于特定的数据集，对模型进行二次训练； 小样本学习； 还有第三种方法： 即将整个过程拆分三个步骤： 先让 GPT 解析问题的意图（将用户的问题作为提示关键词，让转成嵌入）； 基于解析后的意图，从数据库中搜索匹配的数据（数据需要提前转成嵌入）； 将数据提交给 GPT，让其整理后返回最终答案； 以上方法规避了每次将整本指南发送给 GPT 的问题。虽然效果不一定很完美，但大部分情况都OK； 语音控制 控制流程示例如下： 可使用语音转文本工具，例如 Whisper，先将语音转成文本；之后是一个状态机，让 GPT 判断用户的意图，然后根据不同的意图，调用不同的接口，来实现意图；当然，有可能用户的意图不明确，此时可让用户提供更多的信息；有点像是一个状态机； 12345678910111213141516171819# 定义discussion函数，它让系统能够在各个状态之间切换：def discussion(messages, last_step): #调用OpenAI API以获取下一个状态 answer = generate_answer(messages) if answer in prompts.keys(): #找到一个新状态，将其添加到消息列表中 messages.append(&#123;&quot;role&quot;: &quot;assistant&quot;, &quot;content&quot;: answer&#125;) messages.append(&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: prompts[answer]&#125;) #递归式遍历状态机return discussion(messages, answer) elif answer in actions.keys(): #新状态是一个动作 do_action(answer) else: #我们处于END状态 #如果上一步是MORE，那么保留消息的历史记录 #否则重新开始if last_step != &#x27;MORE&#x27;: messages=[] last_step = &#x27;END&#x27; return answer 第4章 高级技巧 提示工程 提示词的数量会影响 OpenAI 的使用成本，稳妥起见，最好设置 max_tokens 参数，以便意义发送大量数据，导致费用大幅超支； 设计有效的提示词 提示词的三个要素： 角色 上下文 任务 如何描述上下文，以便 GPT 更好的理解我们的意图，有时候并不容易，因为我们本身对问题也不是非常了解，所以无法提供更具体的信息。遇到这种情况，我们可以询问 GPT 它想知道哪些上下文，让它提问题，我们来回答。 任务：用来告诉 GPT 需要做什么，因此应该尽量描述得具体和明确一些； 角色：用来告诉 GPT 要以什么样的身份给出回答。相同的问题，由不同的角色回答，其答案会有所不同；角色并不是必须的，但使用角色可以让结果更加符合我们的预期； prompt 提示词的作用有点像是函数参数，用来调整 GPT 内部的概率分布，引导模型生成我们想要的结果；上下文+角色+任务只是一种提示词的常用结构，但并不是唯一的结构，完成可以根据任务需要，设计其他更合理的结构； 逐步思考 有时候有些问题可能比较复杂，难以在下一句对话中得出结果。此时可以考虑在提示词中添加 ”Let’s think step by step“（让我们逐步思考），来引导 GPT 模拟中间推理，将一个大问题，拆分成多个小问题进行处理； 以下是模型的输出： 实现少样本学习 少样本学习：在提示词中，给 GPT 提供示例，让其模仿； 以下示例的目标，是让 GPT 将部分文本转成表情； 对于简一些的任务，甚至可以使用单样本，这样有助于减少费用； 提示词工程并没有标准答案，它更像是医学，在反复试错中，找到更好的方案和技巧； 改善提示效果 一些提示词的技巧： 指示模型提出更多的问题 在提示词的结尾，询问模型是否理解问题，并指示模型提出更多的问题，示例如下： 你清楚地理解我的请求了吗？如果没有，请问我关于上下文的问题。这样一来，当我回答时，你就能够更高效地执行我所请求的任务 格式化输出 明确指示结果应该被某种格式化工具所接受 重复指示 在提示词中多次添加相同意图的指令，但指令的表达方式有所不同 使用负面提示 在提示词中举反例，告诉模型自己不想要什么样的结果。这些负面提示在本质上有点像是结果筛选器； 添加长度限制 在提示词明确提出答案应该满足的长度要求，示例如下： 如果你能回答，说 YES；如果你需要更多信息，说 MORE；如果你不能回答，说 NO；回答的长度只限一个单词 微调模型 想要获得预期结果，除了使用提示词技巧外，还有一种策略是微调模型，以便提高模型处理特定任务时的表现； 开始微调 目标：实现一个电子邮件自动回复，邮件内容保持跟之前相同的风格，即使用行业专用语汇 微调的本质是修改模型中原有参数的权重，得到一个新的模型，以更好的适应特定任务； 注：OpenAI 上面有多个基础模型，参数数量不同；其中能够进行微调的模型数量是有限的； 问：什么是 InstructGPT 系列？ 答：对原始模型（GPT-3）的输出，使用人工反馈进行强化学习（RLHF），微调后的新模型； 微调步骤： 选择一个大小合适的基础模型； 准备好足够的数据集，重新训练模型； 对于简单的任务，通常使用少样本学习就够用了。对于特定领域的复杂任务，则需要使用微调模型的方法。但使用这个方法有一个局限性，则受限于可使用的训练数据数量。当任务较为简单，可能几百个训练数据就够了。但如果任务特别复杂，那可能将涉及以万或者百万为单位的数据集。数据集来源不足可能会是一个问题，另外训练成本也将急剧上升； 使用 OpenAI API 进行模型微调 准备数据 数据集是一个 JSONL 文件，相当于多行的 JSON 组成的文件，示例如下： 123&#123;&quot;prompt&quot;: &quot;&lt;prompt text&gt;&quot;, &quot;completion&quot;: &quot;&lt;completion text&gt;&quot;&#125;&#123;&quot;prompt&quot;: &quot;&lt;prompt text&gt;&quot;, &quot;completion&quot;: &quot;&lt;completion text&gt;&quot;&#125;&#123;&quot;prompt&quot;: &quot;&lt;prompt text&gt;&quot;, &quot;completion&quot;: &quot;&lt;completion text&gt;&quot;&#125; OpenAI 有自带一个格式转换的命令行工具，可用来协助生成数据集， 1openai tools fine_tunes.prepare_data -f &lt;LOCAL_FILE&gt; 上传数据 1234openai.File.create( file=open(&quot;out_openai_completion_prepared.jsonl&quot;, &quot;rb&quot;), purpose=&#x27;fine-tune&#x27; # 此参数表示要微调模型) 调用 OpenAI 内置函数上传数据，该函数会返回一个对象；对象中有文件 ID，该 ID 可作为创建模型的参数，以便创建模型时，可引用该份已上传的数据； 创建模型 上传完训练数据后，OpenAI 服务端会开启一个训练作业。可调用函数查询该作业的排队和训练的进度状态； 微调的应用场景 法律文本分析：因为法律文件一般包含很多法律术语，所以微调模型可以显著提高性能； 自动代码审查：例如 Github 的 Copilot； 财务报表摘要 技术文档翻译：同样是包含诸多专业术语； 根据以上的应用场景可以发现，微调模型特别适用于在专业领域中生成专业的内容，例如某个特定领域的客服聊天机器人； 案例演示：电子邮件营销 目的：使用电子邮件，向目标用户（线下商店）推广在线支付服务（例如微信、支付宝等）； 步骤如下： 创建合成的数据集 理论上最理想的办法是使用人工来创建训练数据，但如果需要的数据量很大，会导致成本很高，并不划算。因此我们也可以考虑让 GPT 生成一些数据； 123456# 区别不同类型、不同城市、不同规模的商店，以便生成有针对性的内容l_sector = [&#x27;Grocery Stores&#x27;, &#x27;Restaurants&#x27;, &#x27;Fast Food Restaurants&#x27;, &#x27;Pharmacies&#x27;, &#x27;Service Stations (Fuel)&#x27;, &#x27;Electronics Stores&#x27;]l_city = [&#x27;Brussels&#x27;, &#x27;Paris&#x27;, &#x27;Berlin&#x27;]l_size = [&#x27;small&#x27;, &#x27;medium&#x27;, &#x27;large&#x27;] 123456789101112131415161718# 创建提示词，将类型、城市、规模设置为参数f_prompt = &quot;&quot;&quot;Role: You are an expert content writer with extensive direct marketingexperience. You have strong writing skills, creativity, adaptability todifferent tones and styles, and a deep understanding of audience needsand preferences for effective direct campaigns.Context: You have to write a short message in no more than 2 sentencesfor a direct marketing campaign to sell a new e-commerce paymentservice to stores.The target stores have the following three characteristics:- The sector of activity: &#123;sector&#125;- The city where the stores are located: &#123;city&#125;- The size of the stores: &#123;size&#125;Task: Write a short message for the direct marketing campaign. Use theskills defined in your role to write this message! It is important thatthe message you create takes into account the product you are sellingand the characteristics of the store you are writing to.&quot;&quot;&quot; 12# sub_prompt 将作为键，合成的数据作为值，组成训练数据集f_sub_prompt = &quot;&#123;sector&#125;, &#123;city&#125;, &#123;size&#125;&quot; 12345678910111213141516# 合成数据df = pd.DataFrame()for sector in l_sector: for city in l_city: for size in l_size: for i in range(3): # 每个重复3次 prompt = f_prompt.format(sector=sector, city=city, size=size) sub_prompt = f_sub_prompt.format(sector=sector, city=city, size=size) response_txt = chat_completion( prompt, model=&quot;gpt-3.5-turbo&quot;, temperature=1 ) new_row = &#123;&quot;prompt&quot;: sub_prompt, &quot;completion&quot;: response_txt&#125; new_row = pd.DataFrame([new_row]) df = pd.concat([df, new_row], axis=0, ignore_index=True)df.to_csv(&quot;out_openai_completion.csv&quot;, index=False) 12# 使用命令行格式化训练数据，该工具会提示我们如何处理数据，可根据其提示进行操作，例如补全换行符openai tools fine_tunes.prepare_data -f out_openai_completion.csv 使用合成的数据训练模型 12345678910# 上传数据ft_file = openai.File.create( file=open(&quot;out_openai_completion_prepared.jsonl&quot;, &quot;rb&quot;), purpose=&quot;fine-tune&quot;)# 训练模型openai.FineTune.create( training_file=ft_file[&quot;id&quot;], model=&quot;davinci&quot;, suffix=&quot;direct_marketing&quot;) 调用函数创建训练模型的作业后，会得到一个 fine_tune_id，该 id 可用来查询进度，也可用于取消或者删除作业； 使用微调后的模型进行文本补全 由于我们之前使用商店关键字 + 广告组成的训练集进行训练，因此，对于微调后的模型，我们现在可以直接使用关键字来获取想要的结果了，例如只需输入提示词：Hotel、New York、Small，模型便会自动生成相应的广告邮件内容了； 1234567openai.Completion.create( model=&quot;davinci:ft-book:direct-marketing-2023-05-01-15-20-35&quot;, # 调用微调后的模型 prompt=&quot;Hotel, New York, small -&gt;&quot;, # 使用特定格式的提示词，与训练数据中的格式一致 max_tokens=100, temperature=0, stop=&quot;
&quot;) 微调的成本 使用微调模型调用 API 单价会更高一些；以下价格仅供参考，因为 OpenAI 会不断调整价格； 小结 第5章 使用 LangChain 构架和插件增加 LLM 功能 LangChain 框架 LangChain 是一个让开发基于大模型的应用程序变得更加方便的开发框架；它有以下几个核心模块： Models：提供通用的接口，让调用多个不同厂商的大模型变得更方便； Prompts：创建和管理提示词 Indexes：对接本地数据，目前已改名为 Retrieval Chain：用于创建调用序列，以方便组合多个模型或提示词； Agents：用于处理用户的输入，做出判断，并调用合适的工具完成任务； Memory：用于存储中间状态，保持上下文； 动态提示词 12345678910111213141516# 创建一个可动态提问的程序from langchain.chat_models import ChatOpenAIfrom langchain import PromptTemplate, LLMChaintemplate = &quot;&quot;&quot;Question: &#123;question&#125; Let&#x27;s think step by step. Answer: &quot;&quot;&quot;prompt = PromptTemplate( template=template, input_variables=[&quot;question&quot;])llm = ChatOpenAI(model_name=&quot;gpt-4&quot;)llm_chain = LLMChain(prompt=prompt, llm=llm) # LLMChain 组合了模型和提示词question = &quot;&quot;&quot; What is the population of the capital of the country where the Olympic Games were held in 2016? &quot;&quot;&quot;llm_chain.run(question) 12345678910# 得到的输出如下Step 1: Identify the country where the Olympic Games were held in 2016.Answer: The 2016 Olympic Games were held in Brazil.Step 2: Identify the capital of Brazil.Answer: The capital of Brazil is Brasília.Step 3: Find the population of Brasília.Answer: As of 2021, the estimated population of Brasília is around3.1 million. So, the population of the capital of the country wherethe Olympic Games were held in 2016 is around 3.1 million. Note thatthis is an estimate and may vary slightly.&#x27; 智能体及工具 智能体及工具是 LangChain 框架的核心功能，它将一些常用的功能，抽象并集成成更容易调用的方式； 逐步思考是一个很强大的范式，它能够利用模型来解决一些复杂的问题；原理也不复杂，相当于将一个复杂的问题，拆解成多个简单的小问题；智能体的一个功能就是内隐了这种范式，用户没有感知； 步骤如下： 智能体收到用户的输入； 智能体分析输入，决定要使用的工具，以及要输入给工具的文本； 智能体调用工具，接收工具输出的文本； 智能体将收到的文本输入，作为输入，输入到智能体的上下文中 重复步骤 2 到步骤 4，直到智能体不再需要调用工具后，将结果输出给用户； 123456789101112from langchain.chat_models import ChatOpenAIfrom langchain.agents import load_tools, initialize_agent, AgentTypellm = ChatOpenAI(model_name=&quot;gpt-3.5-turbo&quot;, temperature=0)tools = load_tools([&quot;wikipedia&quot;, &quot;llm-math&quot;], llm=llm)agent = initialize_agent( tools, llm, agent=AgentType.ZERO_SHOT_REACT_DESCRIPTION, verbose=True)question = &quot;&quot;&quot;What is the square root of the population of the capitalof the Country where the Olympic Games were held in 2016?&quot;&quot;&quot;agent.run(question) 12345678910# 计算过程如下&gt; Entering new chain...I need to find the country where the Olympic Games were held in 2016and then find the population of its capital city. Then I can take thesquare root of that population.Action: WikipediaAction Input: &quot;2016 Summer Olympics&quot;Observation: Page: 2016 Summer Olympics[...] 123456789101112Thought:I need to search for the capital city of Brazil.Action: WikipediaAction Input: &quot;Capital of Brazil&quot;Observation: Page: Capitals of BrazilSummary: The current capital of Brazil, since its construction in1960, is Brasilia. [...]Thought: I have found the capital city of Brazil, which is Brasilia.Now I need to find the population of Brasilia.Action: WikipediaAction Input: &quot;Population of Brasilia&quot;Observation: Page: Brasilia[...] 123456Thought: I have found the population of Brasilia, but I need tocalculate the square root of that population.Action: Calculator # 此处调用了计算器Action Input: Square root of the population of Brasilia (population:found in previous observation)Observation: Answer: 1587.051038876822 12345# 得出最终的答案Thought: I now know the final answerFinal Answer: The square root of the population of the capital of thecountry where the Olympic Games were held in 2016 is approximately 1587.&gt; Finished chain. 记忆 记忆之前的状态，相当于记住上下文，这在某些场景中是必须和有用的，例如构建聊天机器人 123456# 有专门的 ConversationChainfrom langchain import OpenAI, ConversationChainchatbot_llm = OpenAI(model_name=&#x27;text-ada-001&#x27;)chatbot = ConversationChain(llm=chatbot_llm , verbose=True)chatbot.predict(input=&#x27;Hello&#x27;) 123456789101112# 输出结果如下&gt; Entering new ConversationChain chain...Prompt after formatting: # 虽然用户只输入了 Hello，但实际上 LangChain 提交给模型的提示词要多很多The following is a friendly conversation between a human and anAI. The AI is talkative and provides lots of specific details fromits context. If the AI does not know the answer to a question, ittruthfully says it does not know.Current conversation:Human: HelloAI:&gt; Finished chain.&#x27; Hello! How can I help you?&#x27; 1234567891011# 在后续的对话中，LangChain 会将聊天记录提交给模型&gt; Entering new ConversationChain chain...Prompt after formatting:The following [...] does not know.Current conversation:Human: HelloAI: Hello! How can I help you?Human: Can I ask you a question? Are you an AI?AI:&gt; Finished chain.&#x27;

Yes, I am an AI.&#x27; 有些模型如 GPT-4 有专门针对聊天场景的微调模型，有时候使用这些微调模型效果更好，不一定非要用 LangChain 的接口； 嵌入 嵌入用于将模型与本地的数据相结合，这样模型的回答将更有针对性，例如之前讨论过的游戏说明书的案例； 123from langchain.document_loaders import PyPDFLoaderloader = PyPDFLoader(&quot;ExplorersGuide.pdf&quot;)pages = loader.load_and_split() # 加载 PDF 文件，并将其分页 12from langchain.embeddings import OpenAIEmbeddingsembeddings = OpenAIEmbeddings() # 用于转分页的 PDF 内容转换成向量，并保存到数据库中 123# 之后当用户输入问题时，就到数据库中查询相近的嵌入q = &quot;What is Link&#x27;s traditional outfit color?&quot;db.similarity_search(q)[0] 12345# 查询结果如下，从数据库中查询到与问题最相关的页面Document(page_content=&#x27;&#x27;&#x27;While Link’s traditional green tunic is certainly an iconic look, his wardrobe has expanded [...] Dress for Success&#x27;&#x27;&#x27;, metadata=&#123;&#x27;source&#x27;: &#x27;ExplorersGuide.pdf&#x27;, &#x27;page&#x27;: 35&#125;) 12345678910# 将嵌入整合到聊天机器人中，让聊天机器人可以回答用户的提问from langchain.chains import RetrievalQAfrom langchain import OpenAIllm = OpenAI()# 注意此处的 retriever 用到了向量数据库，它将提取最相近的嵌入，然后做为上下文和问题一起发给模型chain = RetrievalQA.from_llm(llm=llm, retriever=db.as_retriever()) q = &quot;What is Link&#x27;s traditional outfit color?&quot;chain(q, return_only_outputs=True) GPT-4 插件 插件主要用于实时获取一些必要数据，它的功能不需要模型实现，而是由开发者实现好的，供模型进行调用。调用这些插件后，它会返回必要的数据，做为上下文参数发给模型，这样模型便能够处理更加复杂的任务，例如查询实时的比赛分数、股票价格、机票价格、预定机票等； 插件 API 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647# 以下代码定义了一个 Todo 待办事项程序的 web 接口import jsonimport quart # quart 是一个 web 框架，类似 flask 那种类型import quart_corsfrom quart import requestapp = quart_cors.cors( quart.Quart(__name__), allow_origin=&quot;https://chat.openai.com&quot;)_TODOS = &#123;&#125; # 跟踪待办事项，如果Python会话重新启动，则数据会丢失@app.post(&quot;/todos/&lt;string:username&gt;&quot;)async def add_todo(username): request = await quart.request.get_json(force=True) if username not in _TODOS: _TODOS[username] = [] _TODOS[username].append(request[&quot;todo&quot;]) return quart.Response(response=&quot;OK&quot;, status=200)@app.get(&quot;/todos/&lt;string:username&gt;&quot;)async def get_todos(username): return quart.Response( response=json.dumps(_TODOS.get(username, [])), status=200 ) @app.get(&quot;/.well-known/ai-plugin.json&quot;) # 该接口用于提供插件信息，以便模型安装该插件async def plugin_manifest(): host = request.headers[&quot;Host&quot;] with open(&quot;./.well-known/ai-plugin.json&quot;) as f: text = f.read() return quart.Response(text, mimetype=&quot;text/json&quot;) @app.get(&quot;/openapi.yaml&quot;) # 该接口用于提供 OpenAPI 的调用规范，方便模型了解如何使用插件async def openapi_spec(): host = request.headers[&quot;Host&quot;] with open(&quot;openapi.yaml&quot;) as f: text = f.read() return quart.Response(text, mimetype=&quot;text/yaml&quot;) def main(): app.run(debug=True, host=&quot;0.0.0.0&quot;, port=5003)if __name__ == &quot;__main__&quot;: main() 插件信息 以下是 ai-plugin.json 文件示例 1234567891011121314151617181920&#123; &quot;schema_version&quot;: &quot;v1&quot;, &quot;name_for_human&quot;: &quot;TODO Plugin&quot;, &quot;name_for_model&quot;: &quot;todo&quot;, &quot;description_for_human&quot;: &quot;Plugin for managing a TODO list. \ You can add, remove and view your TODOs.&quot;, &quot;description_for_model&quot;: &quot;Plugin for managing a TODO list. \ You can add, remove and view your TODOs.&quot;, &quot;auth&quot;: &#123; &quot;type&quot;: &quot;none&quot; &#125;, &quot;api&quot;: &#123; &quot;type&quot;: &quot;openapi&quot;, &quot;url&quot;: &quot;http://localhost:3333/openapi.yaml&quot;, &quot;is_user_authenticated&quot;: false &#125;, &quot;logo_url&quot;: &quot;http://localhost:3333/logo.png&quot;, &quot;contact_email&quot;: &quot;support@thecompany.com&quot;, &quot;legal_info_url&quot;: &quot;http://thecompany-url/legal&quot;&#125; OpenAPI 规范 123456789101112131415161718192021222324252627282930# 以下是 openapi.yaml 示例，详细描述接口的调用方法openapi: 3.0.1info: title: TODO Plugin description: A plugin that allows the user to create and manage a TODO list using ChatGPT. If you do not know the user&#x27;s username, ask them first before making queries to the plugin. Otherwise, use the username &quot;global&quot;. version: &#x27;v1&#x27;servers: - url: http://localhost:5003paths: /todos/&#123;username&#125;: get: operationId: getTodos summary: Get the list of todos parameters: - in: path name: username schema: type: string required: true description: The name of the user. responses: &quot;200&quot;: description: OK content: application/json: schema: $ref: &#x27;#/components/schemas/getTodosResponse&#x27; 插件描述 openapi.yaml 中应该尽量描述接口的用途，这样有助于模型判断何时可调用接口获得数据，以及如何调用接口；这其中最重要的字段便是 description_for_model，这个字段是对于插件的功能描述；应该尽量写得清晰易懂，一目了然； 功能描述应该是声明式的，而不是命令式的；
